import math
import random


class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = 0.0
        self.trust = {}
        self.observed_good = {}
        self.observed_bad = {}
        self.round_num = 0
        self.my_history = []
        self.opponent_id = None

    def decide(self) -> bool:
        self.round_num += 1
        opp = self._ctx_opponent_id
        self.opponent_id = opp
        # Default: cooperate unless we have specific reason not to
        # Use a simple heuristic based on trust and reputation
        trust_val = self.trust.get(opp, 0.0)
        my_reputation = self.reputation
        # If opponent has low trust or my reputation is low, we might defect
        # Combine with some noise for exploration
        if trust_val < -0.5:
            return False
        if trust_val > 0.5:
            return True
        # Otherwise decide based on reputation and random chance
        p = 0.5 + 0.3 * trust_val - 0.1 * my_reputation
        p = max(0.1, min(0.9, p))
        return random.random() < p

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation of observed agents
        # If someone cooperates, their reputation increases; if defects, decreases
        if donor_action == 'cooperate':
            self.reputation_of(donor_id, +1)
        else:
            self.reputation_of(donor_id, -1)
        if recipient_action == 'cooperate':
            self.reputation_of(recipient_id, +1)
        else:
            self.reputation_of(recipient_id, -1)

        # Update trust based on observations if we are third-party
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            # If donor cooperates and recipient cooperates, good sign
            if donor_action == 'cooperate' and recipient_action == 'cooperate':
                self.adjust_trust(donor_id, +0.2)
                self.adjust_trust(recipient_id, +0.2)
            elif donor_action == 'defect' and recipient_action == 'defect':
                self.adjust_trust(donor_id, -0.2)
                self.adjust_trust(recipient_id, -0.2)
            elif donor_action == 'cooperate' and recipient_action == 'defect':
                self.adjust_trust(donor_id, -0.1)
                self.adjust_trust(recipient_id, -0.1)
            else:
                self.adjust_trust(donor_id, -0.1)
                self.adjust_trust(recipient_id, -0.1)

        # Self-judgment: update my own reputation based on my action
        if donor_id == self.agent_id:
            if donor_action == 'cooperate':
                self.reputation += 0.1
            else:
                self.reputation -= 0.1
            # Also update trust toward recipient
            if recipient_action == 'cooperate':
                self.adjust_trust(recipient_id, +0.3)
            else:
                self.adjust_trust(recipient_id, -0.3)
        if recipient_id == self.agent_id:
            if recipient_action == 'cooperate':
                self.reputation += 0.1
            else:
                self.reputation -= 0.1
            if donor_action == 'cooperate':
                self.adjust_trust(donor_id, +0.3)
            else:
                self.adjust_trust(donor_id, -0.3)

        # Clamp reputation to avoid extremes
        self.reputation = max(-1.0, min(1.0, self.reputation))

    def reputation_of(self, agent_id: int, delta: float) -> None:
        # Keep a simple dict for reputation, but we only store the main reputation for self
        # For others we just adjust trust indirectly
        pass

    def adjust_trust(self, agent_id: int, delta: float) -> None:
        old = self.trust.get(agent_id, 0.0)
        new = old + delta
        # Clamp to [-1, 1]
        new = max(-1.0, min(1.0, new))
        self.trust[agent_id] = new

import math
import random


class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self._ctx_opponent_id = None
        self.reputation = {}
        self.cooperation_counts = {}
        self.defection_counts = {}
        self.round_num = 0
        self.generation_num = 0
        self.own_actions = []
        self.opponent_actions = []
        self.last_opponent = None
        self.partner_coop_history = []
        self.trust_scores = {}
        self.personal_threshold = 0.5
        self.exploration_rate = 0.1
        self.initial_trust = 0.5
        self.memory_limit = 20
        self.recent_outcomes = []
        self.n_agents = 15
        self.self_coop_count = 0
        self.self_defect_count = 0
        self.observed_coop = {}
        self.observed_defect = {}
        self.observed_total = {}
        self.agent_types = {}
        self.current_opponent_reputation = 0.5
        self.strategy_matrix = {}
        self.sigmoid_scale = 5.0
        self.trust_update_rate = 0.2
        self.reputation_update_rate = 0.1
        self.cooperation_bias = 0.1
        self.defection_penalty = 0.05
        self.forgiveness = 0.05
        self.last_decisions = []
        self.last_actions = {}
        self.own_last_action = None
        self.opponent_last_action = None

    def _initialize_agent(self, agent_id):
        if agent_id not in self.reputation:
            self.reputation[agent_id] = self.initial_trust
            self.cooperation_counts[agent_id] = 0
            self.defection_counts[agent_id] = 0
            self.trust_scores[agent_id] = self.initial_trust
            self.observed_coop[agent_id] = 0
            self.observed_defect[agent_id] = 0
            self.observed_total[agent_id] = 0
            self.agent_types[agent_id] = 'unknown'
            self.strategy_matrix[agent_id] = {'CC': 0, 'CD': 0, 'DC': 0, 'DD': 0}

    def _update_trust(self, agent_id, action, my_action):
        # Update trust based on observed action relative to expectation
        current_trust = self.trust_scores.get(agent_id, self.initial_trust)
        if action == 'cooperate':
            # Cooperation increases trust, especially if defection was expected
            expected_coop_prob = self._sigmoid(current_trust)
            if expected_coop_prob < 0.5:
                delta = self.trust_update_rate * (1 - expected_coop_prob) * 0.5
            else:
                delta = self.trust_update_rate * 0.1
            new_trust = current_trust + delta
        else:
            # Defection decreases trust
            expected_coop_prob = self._sigmoid(current_trust)
            delta = self.trust_update_rate * expected_coop_prob * 0.5
            new_trust = current_trust - delta
        # Clamp to [0,1]
        self.trust_scores[agent_id] = max(0.0, min(1.0, new_trust))
        # Also update reputation slowly
        self.reputation[agent_id] = 0.9 * self.reputation.get(agent_id, self.initial_trust) + 0.1 * self.trust_scores[agent_id]

    def _sigmoid(self, x):
        try:
            return 1.0 / (1.0 + math.exp(-self.sigmoid_scale * (x - 0.5)))
        except:
            return 0.5

    def _update_strategy_matrix(self, agent_id, my_action, opp_action):
        key = my_action[0].upper() + opp_action[0].upper()
        if key in self.strategy_matrix[agent_id]:
            self.strategy_matrix[agent_id][key] += 1

    def _update_observed_stats(self, agent_id, action):
        self.observed_total[agent_id] = self.observed_total.get(agent_id, 0) + 1
        if action == 'cooperate':
            self.observed_coop[agent_id] = self.observed_coop.get(agent_id, 0) + 1
        else:
            self.observed_defect[agent_id] = self.observed_defect.get(agent_id, 0) + 1

    def _compute_reputation(self, agent_id):
        total = self.observed_total.get(agent_id, 0)
        if total == 0:
            return self.initial_trust
        coop = self.observed_coop.get(agent_id, 0)
        return coop / total

    def _forget_old(self):
        # Keep memory bounded by removing oldest entries if over limit
        if len(self.partner_coop_history) > self.memory_limit:
            self.partner_coop_history = self.partner_coop_history[-self.memory_limit:]
        if len(self.recent_outcomes) > self.memory_limit:
            self.recent_outcomes = self.recent_outcomes[-self.memory_limit:]

    def decide(self) -> bool:
        opponent_id = self._ctx_opponent_id
        if opponent_id is None:
            return True  # no opponent, cooperate

        self._initialize_agent(opponent_id)

        # Adjust exploration rate based on round progression
        if self.round_num < 5:
            exploration = 0.2
        elif self.round_num < 15:
            exploration = 0.1
        else:
            exploration = 0.05

        # Compute opponent's reputation from observations
        reputation = self._compute_reputation(opponent_id)
        trust = self.trust_scores.get(opponent_id, self.initial_trust)

        # Combine reputation and trust and maybe personal experience
        # If we have personal history, use it more
        personal_history = [a for (a, o) in self.partner_coop_history if o == opponent_id]
        if personal_history:
            personal_coop_rate = sum(1 for a in personal_history if a == 'cooperate') / len(personal_history)
            # Weight personal more if we have many interactions
            weight = min(0.7, len(personal_history) * 0.1)
            combined = weight * personal_coop_rate + (1 - weight) * (0.5 * reputation + 0.5 * trust)
        else:
            combined = 0.5 * reputation + 0.5 * trust

        # Adjust based on opponent's observed strategy tendencies
        strategy = self.strategy_matrix.get(opponent_id, {})
        total_strategy = sum(strategy.values())
        if total_strategy > 0:
            # If opponent tends to defect when we cooperate (CD), be wary
            cd_freq = strategy.get('CD', 0) / total_strategy
            if cd_freq > 0.3:
                combined -= 0.1
            # If opponent tends to cooperate when we defect (DC), maybe exploit
            dc_freq = strategy.get('DC', 0) / total_strategy
            if dc_freq > 0.3:
                combined += 0.05

        # Adaptive threshold based on our own recent outcomes
        if self.recent_outcomes:
            recent_coop = sum(1 for (_, a, o) in self.recent_outcomes if a == 'cooperate' and o == 'cooperate')
            recent_defect = sum(1 for (_, a, o) in self.recent_outcomes if a == 'defect')
            if recent_defect > recent_coop:
                self.personal_threshold += 0.02
            else:
                self.personal_threshold -= 0.01
            self.personal_threshold = max(0.2, min(0.8, self.personal_threshold))

        # Probability of cooperation based on combined score and threshold
        coop_prob = self._sigmoid(combined - self.personal_threshold)

        # Exploration: sometimes random
        if random.random() < exploration:
            return random.random() < 0.5

        # Deterministic decision based on probability
        return random.random() < coop_prob

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Increment round counters based on whether we are involved
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            self.round_num += 1
            # If we are donor or recipient, update our own action history
            if donor_id == self.agent_id:
                self.own_actions.append(donor_action)
                self.own_last_action = donor_action
                self.last_opponent = recipient_id
                if donor_action == 'cooperate':
                    self.self_coop_count += 1
                else:
                    self.self_defect_count += 1
            else:
                self.own_actions.append(recipient_action)
                self.own_last_action = recipient_action
                self.last_opponent = donor_id
                if recipient_action == 'cooperate':
                    self.self_coop_count += 1
                else:
                    self.self_defect_count += 1

            # Update partner history
            partner_action = recipient_action if donor_id == self.agent_id else donor_action
            self.partner_coop_history.append((partner_action, self.last_opponent))
            self.opponent_last_action = partner_action

            # Record outcome for this round
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            opp_action = recipient_action if donor_id == self.agent_id else donor_action
            self.recent_outcomes.append((self.round_num, my_action, opp_action))
            self._forget_old()
        else:
            # Third-party observation
            # Update observed stats for both agents
            self._initialize_agent(donor_id)
            self._initialize_agent(recipient_id)
            self._update_observed_stats(donor_id, donor_action)
            self._update_observed_stats(recipient_id, recipient_action)
            # Update trust based on observed actions relative to expectations
            self._update_trust(donor_id, donor_action, 'unknown')
            self._update_trust(recipient_id, recipient_action, 'unknown')
            # Update strategy matrix for both based on joint action
            self._update_strategy_matrix(donor_id, donor_action, recipient_action)
            self._update_strategy_matrix(recipient_id, recipient_action, donor_action)
            # Classify agent type based on observed behavior
            if donor_action == 'cooperate' and recipient_action == 'cooperate':
                self.agent_types[donor_id] = 'cooperator'
                self.agent_types[recipient_id] = 'cooperator'
            elif donor_action == 'defect' and recipient_action == 'defect':
                self.agent_types[donor_id] = 'defector'
                self.agent_types[recipient_id] = 'defector'
            elif donor_action == 'cooperate' and recipient_action == 'defect':
                if self.agent_types.get(donor_id) != 'cooperator':
                    self.agent_types[donor_id] = 'exploited'
                if self.agent_types.get(recipient_id) != 'defector':
                    self.agent_types[recipient_id] = 'exploiter'
            elif donor_action == 'defect' and recipient_action == 'cooperate':
                if self.agent_types.get(donor_id) != 'defector':
                    self.agent_types[donor_id] = 'exploiter'
                if self.agent_types.get(recipient_id) != 'cooperator':
                    self.agent_types[recipient_id] = 'exploited'
        # After each round, adjust personal threshold slightly based on self experience
        if self.own_last_action is not None and self.opponent_last_action is not None:
            if self.own_last_action == 'cooperate' and self.opponent_last_action == 'defect':
                self.personal_threshold += 0.01
            elif self.own_last_action == 'defect' and self.opponent_last_action == 'cooperate':
                self.personal_threshold -= 0.005
            # Keep in [0.2, 0.8]
            self.personal_threshold = max(0.2, min(0.8, self.personal_threshold))

import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.generation = 0
        self.round = 0
        self.reputation = {}
        self.coop_count = 0
        self.defect_count = 0
        self.total_coop = 0
        self.total_defect = 0
        self.last_decisions = {}
        self.my_last_action = None
        self.opponent_last_action = None
        self.my_history = []
        self.opponent_history = {}
        self.generosity = 0.5
        self.forgiveness = 0.7
        self.trust_threshold = 0.3
        self.retaliation_threshold = 0.6

    def decide(self) -> bool:
        opp_id = getattr(self, '_ctx_opponent_id', None)
        if opp_id is None:
            return True

        # Update round/generation based on calls (approximate)
        self.round += 1
        if self.round > 30:
            self.round = 1
            self.generation += 1

        # Reset per-generation stats if new generation
        if self.round == 1:
            self.last_decisions = {}
            self.my_history = []
            self.opponent_history = {}

        # Get opponent's recent behavior
        opp_rec = self.reputation.get(opp_id, 0.0)
        opp_last = self.opponent_history.get(opp_id, None)

        # Simple strategy: cooperate if opponent has generally good reputation
        # or if they cooperated last time we met; defect if they are bad.
        # Also add some randomness to avoid being too predictable.
        if opp_last is not None:
            if opp_last == 'cooperate':
                return random.random() < self.forgiveness
            else:
                return random.random() < (1 - self.retaliation_threshold)
        else:
            # No history: cooperate with probability based on generosity
            return random.random() < self.generosity

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation for both actors based on their actions
        # Cooperating gives positive reputation, defecting gives negative
        if donor_action == 'cooperate':
            self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) + 0.1
        else:
            self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) - 0.15

        if recipient_action == 'cooperate':
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) + 0.1
        else:
            self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) - 0.15

        # Clamp reputation to [0,1]
        for aid in (donor_id, recipient_id):
            self.reputation[aid] = max(0.0, min(1.0, self.reputation[aid]))

        # Track own actions
        if donor_id == self.agent_id:
            self.my_last_action = donor_action
            self.my_history.append(donor_action)
            if donor_action == 'cooperate':
                self.total_coop += 1
            else:
                self.total_defect += 1
        if recipient_id == self.agent_id:
            self.my_last_action = recipient_action
            self.my_history.append(recipient_action)
            if recipient_action == 'cooperate':
                self.total_coop += 1
            else:
                self.total_defect += 1

        # Track opponent's actions when they are observed
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            # Third-party observation - update reputation of both
            pass
        elif donor_id == self.agent_id:
            # We are donor, record recipient's action
            self.opponent_history[recipient_id] = recipient_action
        elif recipient_id == self.agent_id:
            # We are recipient, record donor's action
            self.opponent_history[donor_id] = donor_action

        # Adapt generosity based on overall cooperation rate
        total_actions = self.total_coop + self.total_defect
        if total_actions > 0:
            self.generosity = 0.3 + 0.4 * (self.total_coop / total_actions)

import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}  # agent_id -> score (0-100)
        self.coop_history = {}  # agent_id -> list of booleans
        self.defect_history = {}  # agent_id -> list of booleans
        self.my_history = []  # (opponent_id, my_action, opponent_action)
        self.generation = 0
        self.round_in_generation = 0
        self.opponent_id = None
        self._ctx_opponent_id = None
        self.cooperation_count = 0
        self.total_rounds = 0
        self.forgiveness = 0.3
        self.initial_trust = 50.0

    def _init_agent(self, agent_id):
        if agent_id not in self.reputation:
            self.reputation[agent_id] = self.initial_trust
            self.coop_history[agent_id] = []
            self.defect_history[agent_id] = []

    def decide(self) -> bool:
        # Use the context opponent if set, else fallback to stored
        if self._ctx_opponent_id is not None:
            self.opponent_id = self._ctx_opponent_id
        if self.opponent_id is None:
            # If somehow no opponent, default to cooperate
            return True
        self._init_agent(self.opponent_id)
        rep = self.reputation[self.opponent_id]
        # Strategy: cooperate if reputation is decent, but add some stochasticity
        # and reciprocate based on recent interactions
        if rep < 30:
            return False
        elif rep < 60:
            # Mixed: probabilistic based on recent cooperation
            recent = self.coop_history[self.opponent_id][-3:] if self.coop_history[self.opponent_id] else []
            if recent and len(recent) >= 3:
                coop_freq = sum(recent) / len(recent)
                return random.random() < (0.5 + 0.4 * coop_freq)
            else:
                return random.random() < 0.6
        else:
            # High rep: cooperate but maybe defect if opponent has defected a lot recently
            recent_defects = self.defect_history[self.opponent_id][-2:] if self.defect_history[self.opponent_id] else []
            if recent_defects and sum(recent_defects) >= 2:
                return random.random() < 0.2
            else:
                return True

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Update generation/round counters lightly, but not necessary for logic
        # We'll update reputation for both donor and recipient based on actions
        # For third-party observations, we update our perception of them.
        # For self-judgment, we also update but maybe differently.
        self._init_agent(donor_id)
        self._init_agent(recipient_id)

        # Record histories
        if donor_id != self.agent_id:
            # Third-party observation of donor
            if donor_action == 'cooperate':
                self.coop_history[donor_id].append(True)
                self.defect_history[donor_id].append(False)
            else:
                self.coop_history[donor_id].append(False)
                self.defect_history[donor_id].append(True)
        if recipient_id != self.agent_id:
            if recipient_action == 'cooperate':
                self.coop_history[recipient_id].append(True)
                self.defect_history[recipient_id].append(False)
            else:
                self.coop_history[recipient_id].append(False)
                self.defect_history[recipient_id].append(True)

        # Update reputations
        # Cooperation increases rep, defection decreases, but with some noise
        # Also consider pair dynamics: mutual cooperation is great, mutual defection is bad
        donor_coop = donor_action == 'cooperate'
        recipient_coop = recipient_action == 'cooperate'
        if donor_id != self.agent_id:
            delta = 5 if donor_coop else -8
            # If both defected, extra penalty
            if not donor_coop and not recipient_coop:
                delta -= 3
            # If donor cooperated but recipient defected, donor gets slight boost (victim)
            elif donor_coop and not recipient_coop:
                delta += 2
            self.reputation[donor_id] = max(0, min(100, self.reputation[donor_id] + delta))
        if recipient_id != self.agent_id:
            delta = 5 if recipient_coop else -8
            if not donor_coop and not recipient_coop:
                delta -= 3
            elif recipient_coop and not donor_coop:
                delta += 2
            self.reputation[recipient_id] = max(0, min(100, self.reputation[recipient_id] + delta))

        # Self-judgment: when I am donor or recipient, adjust my own reputation? 
        # Actually, we can update own reputation based on actions: if I cooperated, good; if defected, bad.
        # But we don't want to become too self-critical, so mild effect.
        if donor_id == self.agent_id:
            if donor_coop:
                self.reputation[self.agent_id] = max(0, min(100, self.reputation[self.agent_id] + 1))
            else:
                self.reputation[self.agent_id] = max(0, min(100, self.reputation[self.agent_id] - 2))
        if recipient_id == self.agent_id:
            if recipient_coop:
                self.reputation[self.agent_id] = max(0, min(100, self.reputation[self.agent_id] + 1))
            else:
                self.reputation[self.agent_id] = max(0, min(100, self.reputation[self.agent_id] - 2))

        # If this is my own interaction, record in my_history
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            opp = recipient_id if donor_id == self.agent_id else donor_id
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            opp_action = recipient_action if donor_id == self.agent_id else donor_action
            self.my_history.append((opp, my_action, opp_action))
            self.total_rounds += 1
            if my_action == 'cooperate':
                self.cooperation_count += 1
            # Update opponent reputation based on my direct experience (weighted more)
            if opp in self.reputation:
                if opp_action == 'cooperate':
                    self.reputation[opp] = max(0, min(100, self.reputation[opp] + 3))
                else:
                    self.reputation[opp] = max(0, min(100, self.reputation[opp] - 5))

import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # reputation: maps agent_id to a score between -1 and 1
        self.reputation = {}
        # cooperation history: maps agent_id to (coops, defections) observed as donor
        self.donor_stats = {}
        # recipient history: maps agent_id to (coops, defections) received as recipient
        self.recipient_stats = {}
        # my own recent actions: list of (donor_action, recipient_action) for self-judgment
        self.self_history = []
        # partner history: maps opponent_id to list of their actions when I played with them
        self.partner_actions = {}
        # round counter within generation (reset by decide? but observe called outside; we'll use len of self_history)
        # For generation tracking, we can approximate by round count from self observations
        self._rounds_seen = 0
