        # New: track partner-specific cooperation counts
        self.partner_coop_count = {}
        self.partner_total_count = {}

    def decide(self) -> bool:
        self.round_num += 1
        opp = self._ctx_opponent_id
        self.opponent_id = opp
        # Default: cooperate unless we have specific reason not to
        # Use a simple heuristic based on trust and reputation
        trust_val = self.trust.get(opp, 0.0)
        my_reputation = self.reputation
        # If opponent has low trust or my reputation is low, we might defect
        # Combine with some noise for exploration
        if trust_val < -0.5:
            return False
        if trust_val > 0.5:
            return True
        # Otherwise decide based on reputation and random chance
        p = 0.5 + 0.3 * trust_val - 0.1 * my_reputation
        p = max(0.1, min(0.9, p))
        return random.random() < p

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation of observed agents
        # If someone cooperates, their reputation increases; if defects, decreases
        if donor_action == 'cooperate':
            self.reputation_of(donor_id, +1)
        else:
            self.reputation_of(donor_id, -1)
        if recipient_action == 'cooperate':
            self.reputation_of(recipient_id, +1)
        else:
            self.reputation_of(recipient_id, -1)

        # Update trust based on observations if we are third-party
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            # If donor cooperates and recipient cooperates, good sign
            if donor_action == 'cooperate' and recipient_action == 'cooperate':
                self.adjust_trust(donor_id, +0.2)
                self.adjust_trust(recipient_id, +0.2)
            elif donor_action == 'defect' and recipient_action == 'defect':
                self.adjust_trust(donor_id, -0.2)
                self.adjust_trust(recipient_id, -0.2)
            elif donor_action == 'cooperate' and recipient_action == 'defect':
                self.adjust_trust(donor_id, -0.1)
                self.adjust_trust(recipient_id, -0.1)
            else:
                self.adjust_trust(donor_id, -0.1)
                self.adjust_trust(recipient_id, -0.1)

        # Self-judgment: update my own reputation based on my action
        if donor_id == self.agent_id:
            if donor_action == 'cooperate':
                self.reputation += 0.1
            else:
                self.reputation -= 0.1
            # Also update trust toward recipient
            if recipient_action == 'cooperate':
                self.adjust_trust(recipient_id, +0.3)
            else:
                self.adjust_trust(recipient_id, -0.3)
            # Track partner cooperation counts when I am donor
            self.partner_total_count[recipient_id] = self.partner_total_count.get(recipient_id, 0) + 1
            if recipient_action == 'cooperate':
                self.partner_coop_count[recipient_id] = self.partner_coop_count.get(recipient_id, 0) + 1
        if recipient_id == self.agent_id:
