            if donor_action == 'cooperate':
                self.adjust_trust(donor_id, +0.3)
            else:
                self.adjust_trust(donor_id, -0.3)
            # Track partner cooperation counts when I am recipient
            self.partner_total_count[donor_id] = self.partner_total_count.get(donor_id, 0) + 1
            if donor_action == 'cooperate':
                self.partner_coop_count[donor_id] = self.partner_coop_count.get(donor_id, 0) + 1

        # Clamp reputation to avoid extremes
        self.reputation = max(-1.0, min(1.0, self.reputation))

