                elif coop_rate < 0.3:
                    self.adjust_trust(pid, -0.1)

    def reputation_of(self, agent_id: int, delta: float) -> None:
        # Keep a simple dict for reputation, but we only store the main reputation for self
        # For others we just adjust trust indirectly
        pass

    def adjust_trust(self, agent_id: int, delta: float) -> None:
        old = self.trust.get(agent_id, 0.0)
        new = old + delta
        # Clamp to [-1, 1]
        new = max(-1.0, min(1.0, new))
        self.trust[agent_id] = new

