class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.interaction_counts = {}
        self.last_action = {}
        self.observed_coop = {}
        self.observed_defect = {}
        self.round = 0
        self.num_agents = None
        self._ctx_opponent_id = None
        self.own_action_history = {}  # key: opponent_id, value: list of (my_action, other_action)

    def _init_agent(self, other_id: int):
        if other_id not in self.reputation:
            self.reputation[other_id] = 0.0
            self.observed_coop[other_id] = 0
            self.observed_defect[other_id] = 0
            self.interaction_counts[(self.agent_id, other_id)] = 0
            self.own_action_history[other_id] = []

    def decide(self) -> bool:
        if self._ctx_opponent_id is None:
            return True
        opp = self._ctx_opponent_id
        self._init_agent(opp)
        if (self.agent_id, opp) not in self.interaction_counts or self.interaction_counts[(self.agent_id, opp)] == 0:
            rep = self.reputation.get(opp, 0.0)
            return rep >= 0.0
        history = self.own_action_history.get(opp, [])
        if not history:
            rep = self.reputation.get(opp, 0.0)
            return rep >= 0.0
        last_my, last_other = history[-1]
        # If we cooperated last time and opponent defected, defect
        if last_my == 'cooperate' and last_other == 'defect':
            return False
        # If opponent cooperated last time, cooperate
        if last_other == 'cooperate':
            return True
        # If we defected last time, sometimes try to re-cooperate
        if last_my == 'defect':
            # Use a forgiving strategy: 30% chance to cooperate
            return random.random() < 0.3
        return True

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.round += 1
        self_involved = (donor_id == self.agent_id or recipient_id == self.agent_id)
        max_id = max(donor_id, recipient_id, self.agent_id)
        if self.num_agents is None or max_id >= self.num_agents:
            self.num_agents = max_id + 1

        self._init_agent(donor_id)
        self._init_agent(recipient_id)

        if donor_action == 'cooperate':
            self.observed_coop[donor_id] = self.observed_coop.get(donor_id, 0) + 1
        else:
            self.observed_defect[donor_id] = self.observed_defect.get(donor_id, 0) + 1

        if recipient_action == 'cooperate':
            self.observed_coop[recipient_id] = self.observed_coop.get(recipient_id, 0) + 1
        else:
            self.observed_defect[recipient_id] = self.observed_defect.get(recipient_id, 0) + 1

        def update_rep(agent_id, action):
            self._init_agent(agent_id)
            total = self.observed_coop.get(agent_id, 0) + self.observed_defect.get(agent_id, 0)
            rep = self.reputation[agent_id]
            target = 1.0 if action == 'cooperate' else -1.0
            alpha = 1.0 / (total + 1)
            self.reputation[agent_id] = rep + alpha * (target - rep)

        update_rep(donor_id, donor_action)
        update_rep(recipient_id, recipient_action)

        if self_involved:
            if donor_id == self.agent_id:
                my_action = donor_action
                other_id = recipient_id
                other_action = recipient_action
            else:
                my_action = recipient_action
                other_id = donor_id
                other_action = donor_action

            key = (self.agent_id, other_id)
            self.interaction_counts[key] = self.interaction_counts.get(key, 0) + 1
            self.last_action[other_id] = (my_action, other_action)
            self.own_action_history[other_id].append((my_action, other_action))

