                if action == 'cooperate':
                    self.coop_counts[agent] = self.coop_counts.get(agent, 0) + 1
                if self.total_counts[agent] > 0:
                    self.reputations[agent] = self.coop_counts[agent] / self.total_counts[agent]

        # Update personal scores
        if donor_id == self.agent_id:
            if recipient_action == 'cooperate':
                self.personal_scores[recipient_id] = self.personal_scores.get(recipient_id, 0.5) * 0.9 + 0.1 * 1.0
            else:
