        self.opp_coop_rate = {}

    def _init_agent(self, other_id: int):
        if other_id not in self.reputation:
            self.reputation[other_id] = 0.0
            self.observed_coop[other_id] = 0
            self.observed_defect[other_id] = 0
            self.interaction_counts[(self.agent_id, other_id)] = 0
            self.opp_coop_rate[other_id] = 0.5

    def decide(self) -> bool:
        if self._ctx_opponent_id is None:
            return True
        opp = self._ctx_opponent_id
        self._init_agent(opp)
        # Use a mixed strategy: mostly cooperate but defect if opponent's cooperation rate is low
        # Also consider reputation as a secondary signal
        coop_rate = self.opp_coop_rate.get(opp, 0.5)
        rep = self.reputation.get(opp, 0.0)
        # If we have interacted, use more direct feedback
        key = (self.agent_id, opp)
        if key in self.interaction_counts and self.interaction_counts[key] > 0:
            # If opponent's recent action was defection, we defect; otherwise cooperate
            if opp in self.last_action:
                my_last, other_last = self.last_action[opp]
                if other_last == 'defect':
                    return False
                else:
                    return True
        # No direct interaction yet: use cooperation rate and reputation
        # Cooperate if cooperation rate > 0.4, else defect
        return coop_rate > 0.4 or (coop_rate > 0.2 and rep >= 0)

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.round += 1
        self_involved = (donor_id == self.agent_id or recipient_id == self.agent_id)
        max_id = max(donor_id, recipient_id, self.agent_id)
        if self.num_agents is None or max_id >= self.num_agents:
            self.num_agents = max_id + 1

        self._init_agent(donor_id)
        self._init_agent(recipient_id)

        if donor_action == 'cooperate':
            self.observed_coop[donor_id] = self.observed_coop.get(donor_id, 0) + 1
        else:
