            alpha = 0.1
            target = 1.0 if action == 'cooperate' else 0.0
            self.opp_coop_rate[agent_id] = self.opp_coop_rate.get(agent_id, 0.5) + alpha * (target - self.opp_coop_rate[agent_id])

        update_coop_rate(donor_id, donor_action)
        update_coop_rate(recipient_id, recipient_action)

        # Update reputation as before
        def update_rep(agent_id, action):
            self._init_agent(agent_id)
            total = self.observed_coop.get(agent_id, 0) + self.observed_defect.get(agent_id, 0)
            rep = self.reputation[agent_id]
            target = 1.0 if action == 'cooperate' else -1.0
            alpha = 1.0 / (total + 1)
