        if opp in self.opponent_actions_when_playing and len(self.opponent_actions_when_playing[opp]) > 0:
            recent = self.opponent_actions_when_playing[opp][-3:]
            if recent.count(False) > recent.count(True):
                return False
            if rep < 0.4:
