            # Change: Incorporate consistency score into cooperation probability
            consistency = self.consistency_scores.get(opp, 0.5)
            coop_prob = min(1.0, max(0.0, 0.5 + (rep - 0.5) * 1.0 + (consistency - 0.5) * 0.5))
            return random.random() < coop_prob
        else:
            return rep >= 0.5

