                self.defection_counts[agent_id] = self.defection_counts.get(agent_id, 0) + 1
                # Track first encounter defections
                if agent_id not in self.first_encounter_defections:
                    self.first_encounter_defections[agent_id] = 1
            old = self.reputation.get(agent_id, 0.5)
            new = max(0.0, min(1.0, old + delta))
            self.reputation[agent_id] = new

