class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputations = {}
        self.coop_counts = {}
        self.total_counts = {}
        self.personal_scores = {}
        self.recent_coop = {}
        self.generosity = 0.7
        self.trust_threshold = 0.5
        self.initial_reputation = 0.6
        self.punishment_memory = {}
        self.last_own_action = None
        self.last_opponent = None
        self.reciprocity_bonus = 0.1
        # Mutation: Add a forgiveness factor to reduce punishment memory over time
        self.forgiveness = 0.2
        # New mutation: Add a suspicion factor to increase trust threshold for unknown agents
        self.suspicion = 0.05

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True

        rep = self.get_reputation(opponent)
        personal = self.personal_scores.get(opponent, 0.5)
        # Mutation: Increased suspicion for agents with low reputation
        if rep < 0.3:
            trust = 0.3 * personal + 0.7 * rep - self.suspicion
        else:
            trust = 0.4 * personal + 0.6 * rep

        # Punish known defectors more harshly
        if opponent in self.punishment_memory:
            punish_count = self.punishment_memory[opponent]
            if punish_count >= 3:
                return False
            trust -= 0.1 * punish_count

        # New: If opponent cooperated last time we interacted, give slight bonus
        if opponent == self.last_opponent and self.last_own_action == 'cooperate':
            if opponent in self.recent_coop and len(self.recent_coop[opponent]) > 0:
                last_opponent_action = self.recent_coop[opponent][-1]
                if last_opponent_action == 1:
                    trust += self.reciprocity_bonus

        # Mutation: Add a forgiveness component - if the opponent has a good reputation but previously punished, reduce the punishment effect
        if opponent in self.punishment_memory and rep > 0.7:
            punish_count = self.punishment_memory[opponent]
            trust += self.forgiveness * punish_count

        if trust < self.trust_threshold - 0.1:
            return False
        if trust > self.trust_threshold + 0.1:
            return True
        return random.random() < self.generosity

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        for agent, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if action in ('cooperate', 'defect'):
                self.total_counts[agent] = self.total_counts.get(agent, 0) + 1
                if action == 'cooperate':
                    self.coop_counts[agent] = self.coop_counts.get(agent, 0) + 1
                if self.total_counts[agent] > 0:
                    self.reputations[agent] = self.coop_counts[agent] / self.total_counts[agent]

        # Update personal scores
        if donor_id == self.agent_id:
            if recipient_action == 'cooperate':
                self.personal_scores[recipient_id] = self.personal_scores.get(recipient_id, 0.5) * 0.9 + 0.1 * 1.0
            else:
                self.personal_scores[recipient_id] = self.personal_scores.get(recipient_id, 0.5) * 0.9 + 0.1 * 0.0
                self.punishment_memory[recipient_id] = self.punishment_memory.get(recipient_id, 0) + 1
        elif recipient_id == self.agent_id:
            if donor_action == 'cooperate':
                self.personal_scores[donor_id] = self.personal_scores.get(donor_id, 0.5) * 0.9 + 0.1 * 1.0
            else:
                self.personal_scores[donor_id] = self.personal_scores.get(donor_id, 0.5) * 0.9 + 0.1 * 0.0
                self.punishment_memory[donor_id] = self.punishment_memory.get(donor_id, 0) + 1

        # Track recent cooperation
        for agent, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent not in self.recent_coop:
                self.recent_coop[agent] = []
            if len(self.recent_coop[agent]) >= 10:
                self.recent_coop[agent].pop(0)
            self.recent_coop[agent].append(1 if action == 'cooperate' else 0)

        # Mutation: Decay punishment memory over time - if an opponent cooperates, reduce their punishment count
        if donor_id == self.agent_id and recipient_action == 'cooperate':
            if recipient_id in self.punishment_memory and self.punishment_memory[recipient_id] > 0:
                self.punishment_memory[recipient_id] -= 1
        if recipient_id == self.agent_id and donor_action == 'cooperate':
            if donor_id in self.punishment_memory and self.punishment_memory[donor_id] > 0:
                self.punishment_memory[donor_id] -= 1

        # Track own last action and opponent for reciprocity detection
        if donor_id == self.agent_id:
            self.last_own_action = donor_action
            self.last_opponent = recipient_id
        elif recipient_id == self.agent_id:
            self.last_own_action = recipient_action
            self.last_opponent = donor_id

    def get_reputation(self, agent_id):
        if agent_id in self.reputations:
            return self.reputations[agent_id]
        else:
            return self.initial_reputation

