        self.last_action = {}
        self.observed_coop = {}
        self.observed_defect = {}
        self.round = 0
        self.num_agents = None
        self._ctx_opponent_id = None
        self.recent_actions = {}
        self.my_recent_actions = {}
        self.defection_after_coop = {}
        self.coop_after_defect = {}  # Track how often opponent cooperates after defecting

    def _init_agent(self, other_id: int):
        if other_id not in self.reputation:
            self.reputation[other_id] = 0.0
            self.observed_coop[other_id] = 0
            self.observed_defect[other_id] = 0
            self.interaction_counts[(self.agent_id, other_id)] = 0
            self.recent_actions[other_id] = []
            self.my_recent_actions[other_id] = []
            self.defection_after_coop[other_id] = [0, 0]
            self.coop_after_defect[other_id] = [0, 0]  # [coops after defect, defect followed by anything]

    def decide(self) -> bool:
        if self._ctx_opponent_id is None:
            return True
        opp = self._ctx_opponent_id
        self._init_agent(opp)
        recent = self.recent_actions.get(opp, [])
        if len(recent) >= 3:
            if recent[-3:].count(False) >= 2:
                return False
        if (self.agent_id, opp) in self.interaction_counts and self.interaction_counts[(self.agent_id, opp)] > 0:
            last = self.last_action.get(opp, (True, True))
            my_last, opp_last = last
            rep = self.reputation.get(opp, 0.0)
            my_recent = self.my_recent_actions.get(opp, [])
            if len(my_recent) >= 3:
                if my_recent[-3:].count(True) >= 2 and rep < 0.5:
                    return False
            if not opp_last:
                # New: if opponent cooperated after defecting in the past, be more forgiving
                if opp in self.coop_after_defect:
                    coops, total = self.coop_after_defect[opp]
                    if total >= 2 and coops / total > 0.5:
                        return True
                if rep > 0.7:
                    return True
                else:
                    return False
            else:
                # New: if opponent has a history of defecting after cooperating, be wary
                if opp in self.defection_after_coop:
