                    new_rep = self.coop_counts[agent] / self.total_counts[agent]
                    old_rep = self.reputations.get(agent, self.initial_reputation)
                    self.reputations[agent] = self.reputation_momentum * old_rep + (1 - self.reputation_momentum) * new_rep

