class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.interaction_counts = {}
        self.last_action = {}
        self.observed_coop = {}
        self.observed_defect = {}
        self.round = 0
        self.num_agents = None
        self._ctx_opponent_id = None
        self.recent_actions = {}
        self.my_recent_actions = {}
        self.defection_after_coop = {}
        self.cooperation_history = {}
        self.punishment_history = {}
        self.total_interactions = {}
        self.coop_advantage = {}

    def _init_agent(self, other_id: int):
        if other_id not in self.reputation:
            self.reputation[other_id] = 0.0
            self.observed_coop[other_id] = 0
            self.observed_defect[other_id] = 0
            self.interaction_counts[(self.agent_id, other_id)] = 0
            self.recent_actions[other_id] = []
            self.my_recent_actions[other_id] = []
            self.defection_after_coop[other_id] = [0, 0]
            self.cooperation_history[other_id] = []
            self.punishment_history[other_id] = []
            self.total_interactions[other_id] = 0
            self.coop_advantage[other_id] = 0.0

    def decide(self) -> bool:
        if self._ctx_opponent_id is None:
            return True
        opp = self._ctx_opponent_id
        self._init_agent(opp)
        recent = self.recent_actions.get(opp, [])
        if len(recent) >= 3:
            if recent[-3:].count(False) >= 2:
                return False
        if (self.agent_id, opp) in self.interaction_counts and self.interaction_counts[(self.agent_id, opp)] > 0:
            last = self.last_action.get(opp, (True, True))
            my_last, opp_last = last
            rep = self.reputation.get(opp, 0.0)
            my_recent = self.my_recent_actions.get(opp, [])
            if len(my_recent) >= 3:
                if my_recent[-3:].count(True) >= 2 and rep < 0.5:
                    return False
            if not opp_last:
                if rep > 0.7:
                    return True
                else:
                    return False
            else:
                if opp in self.defection_after_coop:
                    defs, total = self.defection_after_coop[opp]
                    if total >= 2 and defs / total > 0.6:
                        return False
                if rep < -0.7:
                    return False
                else:
                    return True
        else:
            rep = self.reputation.get(opp, 0.0)
            coop_rate = self._get_cooperation_rate(opp)
            if coop_rate > 0.7:
                return True
            # Mutation: use punishment history to adjust behavior
            punish = self.punishment_history.get(opp, [])
            if len(punish) >= 3 and punish[-3:].count(True) >= 2:
                return False
            return rep >= 0.0

    def _get_cooperation_rate(self, agent_id: int) -> float:
        coop = self.observed_coop.get(agent_id, 0)
        defect = self.observed_defect.get(agent_id, 0)
        total = coop + defect
        if total == 0:
            return 0.5
        return coop / total

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.round += 1
        self_involved = (donor_id == self.agent_id or recipient_id == self.agent_id)
        max_id = max(donor_id, recipient_id, self.agent_id)
        if self.num_agents is None or max_id >= self.num_agents:
            self.num_agents = max_id + 1

        self._init_agent(donor_id)
        self._init_agent(recipient_id)

        if donor_action == 'cooperate':
            self.observed_coop[donor_id] = self.observed_coop.get(donor_id, 0) + 1
        else:
            self.observed_defect[donor_id] = self.observed_defect.get(donor_id, 0) + 1

        if recipient_action == 'cooperate':
            self.observed_coop[recipient_id] = self.observed_coop.get(recipient_id, 0) + 1
        else:
            self.observed_defect[recipient_id] = self.observed_defect.get(recipient_id, 0) + 1

        def update_rep(agent_id, action):
            self._init_agent(agent_id)
            total = self.observed_coop.get(agent_id, 0) + self.observed_defect.get(agent_id, 0)
            rep = self.reputation[agent_id]
            target = 1.0 if action == 'cooperate' else -1.0
            alpha = 1.0 / (total + 1)
            self.reputation[agent_id] = rep + alpha * (target - rep)

        update_rep(donor_id, donor_action)
        update_rep(recipient_id, recipient_action)

        if self_involved:
            if donor_id == self.agent_id:
                my_action = donor_action
                other_id = recipient_id
                other_action = recipient_action
            else:
                my_action = recipient_action
                other_id = donor_id
                other_action = donor_action

            key = (self.agent_id, other_id)
            self.interaction_counts[key] = self.interaction_counts.get(key, 0) + 1
            self.last_action[other_id] = (my_action, other_action)
            self.recent_actions[other_id].append(other_action == 'cooperate')
            self.my_recent_actions[other_id].append(my_action == 'cooperate')
            self.cooperation_history[other_id].append(other_action == 'cooperate')
            self.total_interactions[other_id] += 1
            # Track if we punished (defected) after their action
            if my_action != 'cooperate':
                self.punishment_history[other_id].append(True)
            else:
                self.punishment_history[other_id].append(False)
            if len(self.cooperation_history[other_id]) > 5:
                self.cooperation_history[other_id] = self.cooperation_history[other_id][-5:]
            if len(self.recent_actions[other_id]) > 5:
                self.recent_actions[other_id] = self.recent_actions[other_id][-5:]
            if len(self.my_recent_actions[other_id]) > 5:
                self.my_recent_actions[other_id] = self.my_recent_actions[other_id][-5:]
            if len(self.punishment_history[other_id]) > 5:
                self.punishment_history[other_id] = self.punishment_history[other_id][-5:]
            if my_action == 'cooperate':
                self.defection_after_coop[other_id][1] += 1
                if other_action != 'cooperate':
                    self.defection_after_coop[other_id][0] += 1
            # Update coop advantage: how much better cooperating is vs defecting
            if self.total_interactions[other_id] > 0:
                if other_action == 'cooperate':
                    self.coop_advantage[other_id] += 1.0
                else:
                    self.coop_advantage[other_id] -= 0.5
                # Normalize
                self.coop_advantage[other_id] = max(-5, min(5, self.coop_advantage[other_id]))

