        if self._ctx_opponent_id is None:
            return True
        opp = self._ctx_opponent_id
        self._init_agent(opp)
        recent = self.recent_actions.get(opp, [])
        if len(recent) >= 3:
            if recent[-3:].count(False) >= 2:
                return False
        if self.consecutive_defections.get(opp, 0) >= 3:
            return False
        if (self.agent_id, opp) in self.interaction_counts and self.interaction_counts[(self.agent_id, opp)] > 0:
