            if len(self.outcome_history[other_id]) > 5:
                self.outcome_history[other_id] = self.outcome_history[other_id][-5:]
            self.cooperation_history[other_id].append(other_action == 'cooperate')
            if len(self.cooperation_history[other_id]) > 5:
                self.cooperation_history[other_id] = self.cooperation_history[other_id][-5:]
            if len(self.recent_actions[other_id]) > 5:
                self.recent_actions[other_id] = self.recent_actions[other_id][-5:]
            if len(self.my_recent_actions[other_id]) > 5:
                self.my_recent_actions[other_id] = self.my_recent_actions[other_id][-5:]
            # Update defection-after-coop tracking
            if my_action == 'cooperate':
                self.defection_after_coop[other_id][1] += 1
                if other_action != 'cooperate':
