            my_last, opp_last = last
            rep = self.reputation.get(opp, 0.0)
            my_recent = self.my_recent_actions.get(opp, [])
            if len(my_recent) >= 3:
                if my_recent[-3:].count(True) >= 2 and rep < 0.5:
