                    self._init_agent(agent_id)
                    other_id = recipient_id if agent_id == donor_id else donor_id
                    self._init_agent(other_id)
                    # Update trust bias: cooperative actions toward cooperative partners increase trust
                    if action == 'cooperate' and other_action == 'cooperate':
                        self.trust_bias[agent_id] = self.trust_bias.get(agent_id, 0.0) + 0.05
                    elif action == 'cooperate' and other_action != 'cooperate':
