                coop = self.observed_coop.get(agent_id, 0)
                defect = self.observed_defect.get(agent_id, 0)
                total = coop + defect
                if total > 0:
                    self.partner_coop_ratio[agent_id] = coop / total

        if self_involved:
            if donor_id == self.agent_id:
