        if len(recent) >= 3:
            if recent[-3:].count(False) >= 2:
                return False
        if (self.agent_id, opp) in self.interaction_counts and self.interaction_counts[(self.agent_id, opp)] > 0:
            last = self.last_action.get(opp, (True, True))
            my_last, opp_last = last
            rep = self.reputation.get(opp, 0.0)
            my_recent = self.my_recent_actions.get(opp, [])
            if len(my_recent) >= 3:
                if my_recent[-3:].count(True) >= 2 and rep < 0.5:
                    return False
            if not opp_last:
                if rep > 0.7:
                    return True
                else:
                    return False
            else:
                outcomes = self.outcome_history.get(opp, [])
                if len(outcomes) >= 3:
                    pattern = outcomes[-3:]
                    if pattern.count(('cooperate', 'defect')) >= 2:
                        return False
                if opp in self.defection_after_coop:
                    defs, total = self.defection_after_coop[opp]
                    if total >= 2 and defs / total > 0.6:
                        return False
                # New: if opponent has betrayed me more than 2 times, be more cautious
                if self.betrayal_count.get(opp, 0) >= 3:
