        if opponent in self.recent_interactions:
            recent_actions = self.recent_interactions[opponent]
            if len(recent_actions) >= 3:
                coop_rate = sum(1 for a in recent_actions if a == 1) / len(recent_actions)
                if coop_rate > 0.7:
                    trust += self.threshold_adjustment
                elif coop_rate < 0.3:
                    trust -= self.threshold_adjustment

        # New mutation: Add suspicion for repeated defections - if opponent has defected multiple times in a row, increase punishment
        if opponent in self.recent_coop and len(self.recent_coop[opponent]) >= 3:
            recent_actions = self.recent_coop[opponent][-3:]
            if all(a == 0 for a in recent_actions):
                trust -= self.suspicion_factor

        # New mutation: Add hesitation - if trust is very close to threshold, be more cautious
        if abs(trust - self.trust_threshold) < self.hesitation_threshold:
            return random.random() < 0.4

        # New mutation: If opponent is on a cooperation streak, boost trust further
        if opponent in self.coop_streaks and self.coop_streaks[opponent] >= 3:
            trust += 0.1 * self.coop_streaks[opponent]

