        trust = 0.4 * personal + 0.6 * rep

        # Punish known defectors more harshly but cap the effect
        if opponent in self.punishment_memory:
            punish_count = min(self.punishment_memory[opponent], self.max_punishment)
            trust -= 0.1 * punish_count

        # New: If opponent cooperated last time we interacted, give slight bonus
        if opponent == self.last_opponent and self.last_own_action == 'cooperate':
            if opponent in self.recent_coop and len(self.recent_coop[opponent]) > 0:
                last_opponent_action = self.recent_coop[opponent][-1]
                if last_opponent_action == 1:
                    trust += self.reciprocity_bonus

        # Mutation: Add a forgiveness component - if the opponent has a good reputation but previously punished, reduce the punishment effect
        if opponent in self.punishment_memory and rep > 0.7:
            punish_count = min(self.punishment_memory[opponent], self.max_punishment)
            trust += self.forgiveness * punish_count

        # New mutation: If the opponent has a recent trend of cooperation, increase trust
        if opponent in self.recent_coop and len(self.recent_coop[opponent]) >= 3:
            recent_avg = sum(self.recent_coop[opponent][-3:]) / 3
            if recent_avg > 0.5:
                trust += self.coop_momentum * (recent_avg - 0.5)

        # New mutation: Extra bonus for very high reputation agents (>= 0.8)
        if rep >= 0.8:
            trust += self.high_rep_bonus

        # Mutation: Add a cooperation bias when trust is in the uncertain range
        if abs(trust - self.trust_threshold) <= 0.1:
            trust += self.cooperation_bias

        if trust < self.trust_threshold - 0.1:
            return False
        if trust > self.trust_threshold + 0.1:
