class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputations = {}
        self.coop_counts = {}
        self.total_counts = {}
        self.personal_scores = {}
        self.recent_coop = {}
        self.generosity = 0.7
        self.trust_threshold = 0.5
        self.initial_reputation = 0.6
        self.punishment_memory = {}
        self.last_own_action = None
        self.last_opponent = None
        self.reciprocity_bonus = 0.1
        self.forgiveness = 0.2
        self.reputation_momentum = 0.8
        self.max_punishment = 2
        self.coop_momentum = 0.7
        self.threshold_adjustment = 0.05
        self.recent_interactions = {}
        self.suspicion_factor = 0.15
        self.hesitation_threshold = 0.1
        self.generosity_decay = 0.01
        self.confidence = 0.5
        self.adaptability = 0.2
        self.consistency_factor = 0.1
        # Mutation: Add a betrayal penalty factor to punish recent defections more heavily
        self.betrayal_factor = 0.25

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True

        rep = self.get_reputation(opponent)
        personal = self.personal_scores.get(opponent, 0.5)
        trust = self.confidence * personal + (1 - self.confidence) * rep

        if opponent in self.punishment_memory:
            punish_count = min(self.punishment_memory[opponent], self.max_punishment)
            trust -= 0.1 * punish_count

        if opponent == self.last_opponent and self.last_own_action == 'cooperate':
            if opponent in self.recent_coop and len(self.recent_coop[opponent]) > 0:
                last_opponent_action = self.recent_coop[opponent][-1]
                if last_opponent_action == 1:
                    trust += self.reciprocity_bonus

        if opponent in self.punishment_memory and rep > 0.7:
            punish_count = min(self.punishment_memory[opponent], self.max_punishment)
            trust += self.forgiveness * punish_count

        if opponent in self.recent_coop and len(self.recent_coop[opponent]) >= 3:
            recent_avg = sum(self.recent_coop[opponent][-3:]) / 3
            if recent_avg > 0.5:
                trust += self.coop_momentum * (recent_avg - 0.5)

        if opponent in self.recent_interactions:
            recent_actions = self.recent_interactions[opponent]
            if len(recent_actions) >= 3:
                coop_rate = sum(1 for a in recent_actions if a == 1) / len(recent_actions)
                if coop_rate > 0.7:
                    trust += self.threshold_adjustment
                elif coop_rate < 0.3:
                    trust -= self.threshold_adjustment

        if opponent in self.recent_coop and len(self.recent_coop[opponent]) >= 3:
            recent_actions = self.recent_coop[opponent][-3:]
            if all(a == 0 for a in recent_actions):
                trust -= self.suspicion_factor

