class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.interaction_counts = {}
        self.last_action = {}
        self.observed_coop = {}
        self.observed_defect = {}
        self.round = 0
        self.num_agents = None
        self._ctx_opponent_id = None
        self.recent_actions = {}
        self.my_recent_actions = {}
        self.defection_after_coop = {}
        self.defection_after_defect = {}
        self.consecutive_defections = {}
        self.partner_coop_ratio = {}
        self.trust_bias = {}
        self.cooperation_history = {}
        self.reputation_volatility = {}
        self.reciprocity_score = {}

    def _init_agent(self, other_id: int):
        if other_id not in self.reputation:
            self.reputation[other_id] = 0.0
            self.observed_coop[other_id] = 0
            self.observed_defect[other_id] = 0
            self.interaction_counts[(self.agent_id, other_id)] = 0
            self.recent_actions[other_id] = []
            self.my_recent_actions[other_id] = []
            self.defection_after_coop[other_id] = [0, 0]
            self.defection_after_defect[other_id] = [0, 0]
            self.cooperation_history[other_id] = []
            self.consecutive_defections[other_id] = 0
            self.partner_coop_ratio[other_id] = 0.5
            self.trust_bias[other_id] = 0.0
            self.reputation_volatility[other_id] = 0.0
            self.reciprocity_score[other_id] = 0.0

    def decide(self) -> bool:
        if self._ctx_opponent_id is None:
            return True
        opp = self._ctx_opponent_id
        self._init_agent(opp)
        recent = self.recent_actions.get(opp, [])
        if len(recent) >= 3:
            if recent[-3:].count(False) >= 2:
                return False
        if self.consecutive_defections.get(opp, 0) >= 3:
            return False
        if (self.agent_id, opp) in self.interaction_counts and self.interaction_counts[(self.agent_id, opp)] > 0:
            last = self.last_action.get(opp, (True, True))
            my_last, opp_last = last
            rep = self.reputation.get(opp, 0.0)
            my_recent = self.my_recent_actions.get(opp, [])
            if len(my_recent) >= 3:
                if my_recent[-3:].count(True) >= 2 and rep < 0.5:
                    return False
            # Modified: more forgiving if opponent has high reciprocity score
            recip = self.reciprocity_score.get(opp, 0.0)
            if not opp_last:
                if rep > 0.7 or recip > 0.3:
                    return True
                else:
                    return False
            else:
                if opp in self.defection_after_coop:
                    defs, total = self.defection_after_coop[opp]
                    if total >= 2 and defs / total > 0.5 and recip <= 0.3:
                        return False
                if opp in self.defection_after_defect:
                    defs, total = self.defection_after_defect[opp]
                    if total >= 2 and defs / total < 0.5:
                        return True
                if rep < -0.7 and recip < 0.2:
                    return False
                else:
                    return True
        else:
            coop_rate = self.partner_coop_ratio.get(opp, 0.5)
            rep = self.reputation.get(opp, 0.0)
            bias = self.trust_bias.get(opp, 0.0)
            adjusted_rep = rep + bias
            if coop_rate > 0.6:
