            target = 1.0 if action == 'cooperate' else -1.0
            alpha = 1.0 / (total + 1)
            new_rep = rep + alpha * (target - rep)
            # New: track volatility of reputation changes
            self.reputation_volatility[agent_id] = self.reputation_volatility.get(agent_id, 0.0) * 0.9 + abs(new_rep - rep) * 0.1
