        # New mutation: Incorporate social health into trust
        if self.reputations:
            avg_rep = sum(self.reputations.values()) / len(self.reputations)
            self.social_health_bonus = 0.1 * (avg_rep - 0.5)
            trust += self.social_health_bonus

        # Dynamic threshold
