        if opponent in self.recent_coop and len(self.recent_coop[opponent]) >= self.suspicion_threshold:
            recent = self.recent_coop[opponent][-self.suspicion_threshold:]
            if all(action == 1 for action in recent):
                trust -= self.suspicion_factor

        # NEW MUTATION: Reputation stability bonus - if opponent's reputation has been stable (low variance), increase trust
        if opponent in self.reputation_stability:
            stability = self.reputation_stability[opponent]
            if stability < self.stability_threshold:
                trust += self.stability_bonus

        # NEW MUTATION: Reciprocity bonus - if we have cooperated with this opponent and they have reciprocated, increase trust
        if opponent in self.reciprocity_tracker:
            history = self.reciprocity_tracker[opponent]
            if len(history) >= 2:
                # Check if opponent tends to reciprocate our cooperation
                coop_count = sum(1 for i in range(1, len(history)) if history[i] == 1 and history[i-1] == 1)
