        freq = self.interaction_frequency.get(opponent, 0)
        threshold_adjustment = self.frequency_threshold_adaptation * (freq - 1)
        dynamic_threshold = self.trust_threshold - (self.observation_count * 0.001) - threshold_adjustment
        dynamic_threshold = max(0.2, min(0.8, dynamic_threshold))

