            self.own_recent_actions.append(1 if recipient_action == 'cooperate' else 0)
            if len(self.own_recent_actions) > 10:
                self.own_recent_actions.pop(0)

        # Update last interaction time
        for agent in [donor_id, recipient_id]:
            self.last_interaction[agent] = self.observation_count

        # Track direct interaction history
        if donor_id == self.agent_id:
            if recipient_id not in self.direct_interaction_history:
                self.direct_interaction_history[recipient_id] = {}
            self.direct_interaction_history[recipient_id]['last_action'] = 1 if recipient_action == 'cooperate' else 0

