        self.cooperation_consistency = {}
        self.consistency_weight = 0.1
        self.consistency_threshold = 0.7

        # NEW MUTATION: Track whether agents are more cooperative with those who cooperate with them (conditional cooperation)
        self.conditional_cooperation = {}
        self.conditional_weight = 0.1
        self.conditional_threshold = 0.6

