    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True

        rep = self.get_reputation(opponent)
        personal = self.personal_scores.get(opponent, 0.5)
        trust = self.personal_weight * personal + (1 - self.personal_weight) * rep

        # Punish known defectors more harshly
        if opponent in self.punishment_memory:
            punish_count = self.punishment_memory[opponent]
            if punish_count >= 3:
                if random.random() < self.risk_threshold:
                    return True
                return False
            trust -= self.punishment_scale * punish_count

        # Mutation: High reputation partners get a significant trust boost
        if rep > self.high_rep_threshold:
            trust += self.high_rep_trust_bonus

        # Mutation: Low reputation partners are penalized more
        if rep < self.low_rep_threshold:
            trust -= self.low_rep_penalty

        # Mutation: Forgiveness for high-reputation partners - reduce punishment impact
        if opponent in self.punishment_memory and rep > self.high_rep_threshold:
            punish_count = self.punishment_memory[opponent]
            trust -= self.punishment_scale * punish_count * (1 - self.rep_forgiveness)

        # Mutation: Long-term cooperation ratio bonus
        if opponent in self.long_term_coop:
            if self.long_term_coop[opponent] > self.long_term_threshold:
                trust += self.long_term_bonus

        # New mutation: Additional penalty for recent defections (within a short window)
        if opponent in self.recent_defections:
            recent_def_count = self.recent_defections[opponent]
            trust -= self.defection_penalty * recent_def_count

        # NEW MUTATION: Add a bonus for agents who cooperate frequently
        if opponent in self.cooperation_frequency:
            if self.cooperation_frequency[opponent] > self.frequency_threshold:
                trust += self.frequency_weight

        # NEW MUTATION: Add a bonus for agents who are observed cooperating with others (third-party reputation)
        if opponent in self.third_party_total_counts:
            if self.third_party_total_counts[opponent] > 0:
                third_party_ratio = self.third_party_coop_counts[opponent] / self.third_party_total_counts[opponent]
                trust += self.third_party_bonus * third_party_ratio

        # NEW MUTATION: Add a bonus for consistent cooperation over time
        if opponent in self.cooperation_consistency:
            consistency = self.cooperation_consistency[opponent]
            if consistency > self.consistency_threshold:
                trust += self.consistency_weight

        # NEW MUTATION: Add bonus for conditional cooperation (cooperating when others cooperate)
        if opponent in self.conditional_cooperation:
            if self.conditional_cooperation[opponent] > self.conditional_threshold:
                trust += self.conditional_weight

        # NEW MUTATION: Sensitivity to reputation - if opponent's reputation is high, increase trust more
        if opponent in self.reputation_sensitivity:
            sensitivity = self.reputation_sensitivity[opponent]
            if sensitivity > self.rep_sensitivity_threshold:
                trust += self.rep_sensitivity_weight * rep

        # NEW MUTATION: If opponent tends to cooperate with high-reputation agents, trust them more
        if opponent in self.reputation_dependent_coop:
            rep_dep = self.reputation_dependent_coop[opponent]
            if rep_dep > self.rep_dep_threshold:
                trust += self.rep_dep_weight * rep

        # NEW MUTATION: If opponent's cooperation trend is improving, add a bonus
        if opponent in self.coop_trend:
            trend = self.coop_trend[opponent]
            if trend > 0:
                trust += self.trend_weight * trend

        # NEW MUTATION: If opponent tends to forgive after being defected against, add a bonus
        if opponent in self.forgiveness_tendency:
            forgiveness = self.forgiveness_tendency[opponent]
            if forgiveness > self.forgiveness_threshold:
                trust += self.forgiveness_weight

        # NEW MUTATION: If opponent cooperates consistently regardless of opponent reputation, add a bonus
        if opponent in self.reputation_consistency:
            rep_consistency = self.reputation_consistency[opponent]
            trust += self.rep_consistency_weight * (1 - rep_consistency)

        # Original logic from parent
        if opponent == self.last_opponent and self.last_own_action == 'cooperate':
            if opponent in self.recent_coop and len(self.recent_coop[opponent]) > 0:
                last_opponent_action = self.recent_coop[opponent][-1]
                if last_opponent_action == 1:
                    trust += self.reciprocity_bonus

        if opponent in self.punishment_memory and rep > 0.7:
            punish_count = self.punishment_memory[opponent]
            trust += self.forgiveness * punish_count

        if opponent in self.recent_coop and len(self.recent_coop[opponent]) >= 2:
            recent = self.recent_coop[opponent][-5:]
            if len(recent) > 1:
                changes = sum(1 for i in range(1, len(recent)) if recent[i] != recent[i-1])
                volatility_factor = changes / max(1, len(recent) - 1)
                trust -= self.volatility * volatility_factor

        if opponent in self.recent_coop and len(self.recent_coop[opponent]) >= 5:
            recent = self.recent_coop[opponent][-5:]
            if all(action == 1 for action in recent):
                trust += self.consistency_bonus

        if opponent in self.recent_coop and len(self.recent_coop[opponent]) >= 6:
            recent = self.recent_coop[opponent][-6:]
            first_half = sum(recent[:3])
            second_half = sum(recent[3:])
            if second_half > first_half:
                trust += self.trend_bonus

        if opponent in self.last_interaction:
            rounds_since = self.observation_count - self.last_interaction[opponent]
            trust -= self.trust_decay * rounds_since

        if opponent in self.punishment_memory and self.punishment_memory[opponent] >= self.retaliation_threshold:
            trust -= 0.2

        # New mutation: Reciprocal behavior bonus
        if opponent in self.reciprocal_histories:
            hist = self.reciprocal_histories[opponent]
            if len(hist) >= 4:
                # Check if opponent tends to cooperate when we cooperated last
                coop_after_our_coop = 0
                total_after_our_coop = 0
                for i in range(1, len(hist)):
                    if hist[i-1][0] == 'cooperate':  # our previous action was cooperate
                        total_after_our_coop += 1
                        if hist[i][1] == 'cooperate':  # opponent cooperates now
                            coop_after_our_coop += 1
                if total_after_our_coop > 0:
                    reciprocal_rate = coop_after_our_coop / total_after_our_coop
                    if reciprocal_rate > self.reciprocal_threshold:
                        trust += self.reciprocal_bonus

        dynamic_threshold = self.trust_threshold - (self.observation_count * 0.001)
        dynamic_threshold = max(0.2, min(0.8, dynamic_threshold))

        self.generosity = max(0.3, self.generosity - self.generosity_decay)
        self.cautiousness = min(0.3, self.cautiousness + self.cautiousness_increment)
        trust -= self.cautiousness

        if random.random() < 0.05:
            return random.random() < 0.6

        if trust < dynamic_threshold - 0.1:
            return random.random() < self.base_coop_probability
        if trust > dynamic_threshold + 0.1:
            return True
        return random.random() < self.generosity

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.observation_count += 1

        # NEW MUTATION: Update cooperation frequency for each observed agent
        for agent, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if action in ('cooperate', 'defect'):
                if agent not in self.cooperation_frequency:
                    self.cooperation_frequency[agent] = 0.5  # initial neutral
                coop_value = 1 if action == 'cooperate' else 0
                self.cooperation_frequency[agent] = 0.9 * self.cooperation_frequency[agent] + 0.1 * coop_value

        # NEW MUTATION: Track third-party cooperation (when agent is not self)
        for agent, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent != self.agent_id and action in ('cooperate', 'defect'):
                self.third_party_total_counts[agent] = self.third_party_total_counts.get(agent, 0) + 1
                if action == 'cooperate':
                    self.third_party_coop_counts[agent] = self.third_party_coop_counts.get(agent, 0) + 1

        # NEW MUTATION: Track consistency of cooperation (variance of recent actions)
        for agent, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if action in ('cooperate', 'defect'):
                if agent not in self.cooperation_consistency:
                    self.cooperation_consistency[agent] = 0.5
                coop_value = 1 if action == 'cooperate' else 0
                # Update consistency as a moving average of how similar the action is to the previous trend
                prev = self.cooperation_consistency[agent]
                # If agent cooperates, increase consistency; if defects, decrease
                self.cooperation_consistency[agent] = 0.9 * prev + 0.1 * coop_value

        # NEW MUTATION: Track conditional cooperation (cooperate when partner cooperates)
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            partner = recipient_id if donor_id == self.agent_id else donor_id
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            partner_action = recipient_action if donor_id == self.agent_id else donor_action
            if partner not in self.conditional_cooperation:
                self.conditional_cooperation[partner] = 0.5
            # If partner cooperates and we cooperate, increase conditional cooperation
            if partner_action == 'cooperate' and my_action == 'cooperate':
                self.conditional_cooperation[partner] = 0.9 * self.conditional_cooperation[partner] + 0.1 * 1.0
            elif partner_action == 'defect' and my_action == 'defect':
                self.conditional_cooperation[partner] = 0.9 * self.conditional_cooperation[partner] + 0.1 * 0.0
            else:
                self.conditional_cooperation[partner] = 0.9 * self.conditional_cooperation[partner] + 0.1 * 0.5

        # NEW MUTATION: Track reputation sensitivity - how much an agent's reputation affects our trust
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            for agent, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
                if agent not in self.reputation_sensitivity:
                    self.reputation_sensitivity[agent] = 0.5
                # If the agent cooperates and has high reputation, increase sensitivity
                current_rep = self.get_reputation(agent)
                if action == 'cooperate' and current_rep > self.high_rep_threshold:
                    self.reputation_sensitivity[agent] = 0.9 * self.reputation_sensitivity[agent] + 0.1 * 1.0
                elif action == 'defect' and current_rep < self.low_rep_threshold:
                    self.reputation_sensitivity[agent] = 0.9 * self.reputation_sensitivity[agent] + 0.1 * 0.0

