        if trust < dynamic_threshold - 0.1:
            return random.random() < self.base_coop_probability
        if trust > dynamic_threshold + 0.1:
            return True
        return random.random() < self.generosity

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.observation_count += 1

        # NEW MUTATION: Update cooperation frequency for each observed agent
        for agent, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if action in ('cooperate', 'defect'):
                if agent not in self.cooperation_frequency:
                    self.cooperation_frequency[agent] = 0.5  # initial neutral
                coop_value = 1 if action == 'cooperate' else 0
                self.cooperation_frequency[agent] = 0.9 * self.cooperation_frequency[agent] + 0.1 * coop_value

        # NEW MUTATION: Track third-party cooperation (when agent is not self)
        for agent, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent != self.agent_id and action in ('cooperate', 'defect'):
                self.third_party_total_counts[agent] = self.third_party_total_counts.get(agent, 0) + 1
                if action == 'cooperate':
                    self.third_party_coop_counts[agent] = self.third_party_coop_counts.get(agent, 0) + 1

        # NEW MUTATION: Track consistency of cooperation (variance of recent actions)
        for agent, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if action in ('cooperate', 'defect'):
                if agent not in self.cooperation_consistency:
                    self.cooperation_consistency[agent] = 0.5
                coop_value = 1 if action == 'cooperate' else 0
                # Update consistency as a moving average of how similar the action is to the previous trend
                prev = self.cooperation_consistency[agent]
                # If agent cooperates, increase consistency; if defects, decrease
                self.cooperation_consistency[agent] = 0.9 * prev + 0.1 * coop_value

        # NEW MUTATION: Track conditional cooperation (cooperate when partner cooperates)
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            partner = recipient_id if donor_id == self.agent_id else donor_id
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            partner_action = recipient_action if donor_id == self.agent_id else donor_action
            if partner not in self.conditional_cooperation:
                self.conditional_cooperation[partner] = 0.5
            # If partner cooperates and we cooperate, increase conditional cooperation
            if partner_action == 'cooperate' and my_action == 'cooperate':
                self.conditional_cooperation[partner] = 0.9 * self.conditional_cooperation[partner] + 0.1 * 1.0
            elif partner_action == 'defect' and my_action == 'defect':
                self.conditional_cooperation[partner] = 0.9 * self.conditional_cooperation[partner] + 0.1 * 0.0
            else:
                self.conditional_cooperation[partner] = 0.9 * self.conditional_cooperation[partner] + 0.1 * 0.5

        # NEW MUTATION: Track reputation sensitivity - how much an agent's reputation affects our trust
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            for agent, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
                if agent not in self.reputation_sensitivity:
                    self.reputation_sensitivity[agent] = 0.5
                # If the agent cooperates and has high reputation, increase sensitivity
                current_rep = self.get_reputation(agent)
                if action == 'cooperate' and current_rep > self.high_rep_threshold:
                    self.reputation_sensitivity[agent] = 0.9 * self.reputation_sensitivity[agent] + 0.1 * 1.0
                elif action == 'defect' and current_rep < self.low_rep_threshold:
                    self.reputation_sensitivity[agent] = 0.9 * self.reputation_sensitivity[agent] + 0.1 * 0.0

import math
