            recent = self.recent_coop[opponent][-5:]
            if len(recent) > 1:
                changes = sum(1 for i in range(1, len(recent)) if recent[i] != recent[i-1])
                volatility_factor = changes / max(1, len(recent) - 1)
                trust -= self.volatility * volatility_factor

        # Consistency bonus
        if opponent in self.recent_coop and len(self.recent_coop[opponent]) >= 5:
            recent = self.recent_coop[opponent][-5:]
            if all(action == 1 for action in recent):
                trust += self.consistency_bonus

        # Trend bonus
        if opponent in self.recent_coop and len(self.recent_coop[opponent]) >= 6:
            recent = self.recent_coop[opponent][-6:]
            first_half = sum(recent[:3])
            second_half = sum(recent[3:])
            if second_half > first_half:
                trust += self.trend_bonus

        # Trust decay
        if opponent in self.last_interaction:
            rounds_since = self.observation_count - self.last_interaction[opponent]
            trust -= self.trust_decay * rounds_since

        # Retaliation
        if opponent in self.punishment_memory and self.punishment_memory[opponent] >= self.retaliation_threshold:
            trust -= 0.2

        # Penalize trust for opponents observed defecting in third-party interactions
        if opponent in self.recent_coop:
            coop_rate = sum(self.recent_coop[opponent]) / max(1, len(self.recent_coop[opponent]))
            if coop_rate < 0.5:
                trust -= self.third_party_defection_penalty * (1 - coop_rate) * 2

        # Boost trust for agents that cooperate in third-party interactions
        if opponent in self.third_party_total_counts and self.third_party_total_counts[opponent] > 0:
            third_party_coop_rate = self.third_party_coop_counts.get(opponent, 0) / self.third_party_total_counts[opponent]
            if third_party_coop_rate > 0.7:
                trust += self.social_coop_bonus

        # Mutation: Add social status bias based on the opponent's reputation relative to the average
        if self.reputations:
            avg_rep = sum(self.reputations.values()) / len(self.reputations)
            if rep > avg_rep:
                trust += self.social_status_bias * self.norm_multiplier
            else:
                trust -= self.social_status_bias * self.norm_multiplier

        # Mutation: Add long-term cooperation bias
        if opponent in self.long_term_coop and self.long_term_coop[opponent] > 0:
            long_term_rate = self.long_term_coop[opponent] / max(1, self.total_counts.get(opponent, 0))
            if long_term_rate > 0.7:
                trust += self.long_term_coop_bias * self.norm_multiplier
            elif long_term_rate < 0.3:
                trust -= self.long_term_coop_bias * 0.5 * self.norm_multiplier

        # Mutation: Add penalty for repeat defections against me
        if opponent in self.defections_against_me_count:
            repeat_defections = self.defections_against_me_count[opponent]
            if repeat_defections >= 2:
                trust -= self.repeat_defection_penalty * (repeat_defections - 1)

        # Mutation: Increase weight on personal experience if we've interacted many times
        if opponent in self.interaction_counts and self.interaction_counts[opponent] >= 5:
            trust = self.personal_rep_weight * personal + (1 - self.personal_rep_weight) * rep

        # Dynamic threshold
        dynamic_threshold = self.trust_threshold - (self.observation_count * 0.001)
        dynamic_threshold = max(0.2, min(0.8, dynamic_threshold))

        # Generosity decay
        self.generosity = max(0.3, self.generosity - self.generosity_decay)

        # Cautiousness increase
        self.cautiousness = min(0.3, self.cautiousness + self.cautiousness_increment)
        trust -= self.cautiousness

        # Exploitation bias increase if we've been defected against a lot
        if self.defections_against_me > 3:
            self.exploitation_bias = min(0.3, self.exploitation_bias + self.exploitation_increment)

        # Mutation: Adjust generosity based on own recent cooperation rate
        if len(self.own_recent_actions) >= 5:
            coop_rate_own = sum(self.own_recent_actions[-5:]) / 5
            if coop_rate_own > 0.8:
                self.generosity = min(0.9, self.generosity + 0.05)
            elif coop_rate_own < 0.2:
                self.generosity = max(0.3, self.generosity - 0.05)

        # Random exploration
        if random.random() < 0.05:
            return random.random() < 0.6

        if trust < dynamic_threshold - 0.1:
            return False
        if trust > dynamic_threshold + 0.1:
            return True
        return random.random() < self.generosity

    def get_reputation(self, agent_id: int) -> float:
        return self.reputations.get(agent_id, self.initial_reputation)

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.observation_count += 1

