        self.high_rep_coop_threshold = 0.8
        # Mutation: Add a bonus for cooperating with partners who have a high reputation
        self.high_rep_bonus = 0.15
        # Mutation: Add a penalty for past defections against us that is proportional to time
        self.time_weighted_penalty = 0.1

        # Mutation: Add a forgiveness factor to reduce punishment memory faster for cooperative partners
        self.forgiveness_factor = 0.3
        # Mutation: Add a recent cooperation bonus to increase trust for recent cooperative behavior
        self.recent_coop_bonus = 0.1
        # Mutation: Add a reputation trend tracking to reward improving reputations
        self.reputation_trends = {}
        self.trend_threshold = 0.02

        # Mutation: Add a long-term memory of interactions to detect stable cooperative patterns
        self.long_term_coop = {}
        # Mutation: Add a suspicion factor that increases when an opponent defects after a long cooperative streak
        self.suspicion_factor = 0.15
        # Mutation: Add a threshold for the number of consecutive cooperations before suspicion kicks in
        self.suspicion_threshold = 5

