    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True

        rep = self.get_reputation(opponent)
        personal = self.personal_scores.get(opponent, 0.5)
        trust = self.personal_weight * personal + (1 - self.personal_weight) * rep

        # Punish known defectors more harshly
        if opponent in self.punishment_memory:
            punish_count = self.punishment_memory[opponent]
            if punish_count >= 3:
                if random.random() < self.risk_threshold:
                    return True
                return False
            trust -= self.punishment_scale * punish_count

        # New mutation: Strong bonus for cooperating with high-reputation partners
        if rep > self.high_rep_coop_threshold:
            trust += self.high_rep_bonus

        # New mutation: Time-weighted penalty for past defections against us
        if opponent in self.punishment_memory:
            time_since_last = self.observation_count - self.last_interaction.get(opponent, 0)
            if time_since_last > 0:
                trust -= self.time_weighted_penalty * punish_count * (1 / (1 + time_since_last * 0.1))

        # New mutation: Cooperation commitment - if we've cooperated with this opponent often recently, increase trust
        if opponent in self.cooperation_commitment and self.cooperation_commitment[opponent] > 0:
            trust += self.cooperation_commitment[opponent] * 0.1

        # New mutation: Distrust decay - if opponent cooperates, reduce negative personal score
        if opponent in self.personal_scores and self.personal_scores[opponent] < 0.5:
