        if opponent in self.recent_coop and len(self.recent_coop[opponent]) >= 2:
            recent = self.recent_coop[opponent][-5:]
            if len(recent) > 1:
                changes = sum(1 for i in range(1, len(recent)) if recent[i] != recent[i-1])
                volatility_factor = changes / max(1, len(recent) - 1)
                trust -= self.volatility * volatility_factor

        if opponent in self.recent_coop and len(self.recent_coop[opponent]) >= 5:
            recent = self.recent_coop[opponent][-5:]
            if all(action == 1 for action in recent):
                trust += self.consistency_bonus

        if opponent in self.recent_coop and len(self.recent_coop[opponent]) >= 6:
            recent = self.recent_coop[opponent][-6:]
            first_half = sum(recent[:3])
            second_half = sum(recent[3:])
            if second_half > first_half:
                trust += self.trend_bonus

        if opponent in self.last_interaction:
            rounds_since = self.observation_count - self.last_interaction[opponent]
            trust -= self.trust_decay * rounds_since

        if opponent in self.punishment_memory and self.punishment_memory[opponent] >= self.retaliation_threshold:
            trust -= 0.2

        # Mutation: Add recent cooperation bonus - if the opponent cooperated in the last interaction, increase trust
        if opponent in self.recent_coop and len(self.recent_coop[opponent]) > 0 and self.recent_coop[opponent][-1] == 1:
            trust += self.recent_coop_bonus

        # Mutation: Add reputation trend bonus - if reputation is improving, increase trust
        if opponent in self.reputation_trends:
            trend = self.reputation_trends[opponent]
            if trend > self.trend_threshold:
                trust += min(0.1, trend * 2)

        # New mutation: Suspicion of long cooperative streaks - if opponent has cooperated many times consecutively, be cautious of a sudden defection
        if opponent in self.recent_coop and len(self.recent_coop[opponent]) >= self.suspicion_threshold:
            recent = self.recent_coop[opponent][-self.suspicion_threshold:]
            if all(action == 1 for action in recent):
                trust -= self.suspicion_factor

        # NEW MUTATION: Reputation stability bonus - if opponent's reputation has been stable (low variance), increase trust
        if opponent in self.reputation_stability:
            stability = self.reputation_stability[opponent]
            if stability < self.stability_threshold:
                trust += self.stability_bonus

        # NEW MUTATION: Reciprocity bonus - if we have cooperated with this opponent and they have reciprocated, increase trust
        if opponent in self.reciprocity_tracker:
            history = self.reciprocity_tracker[opponent]
            if len(history) >= 2:
                # Check if opponent tends to reciprocate our cooperation
                coop_count = sum(1 for i in range(1, len(history)) if history[i] == 1 and history[i-1] == 1)
                total_opportunities = sum(1 for i in range(1, len(history)) if history[i-1] == 1)
                if total_opportunities > 0 and coop_count / total_opportunities > 0.7:
