            trust -= 0.2

        # Mutation: Add recent cooperation bonus - if the opponent cooperated in the last interaction, increase trust
        if opponent in self.recent_coop and len(self.recent_coop[opponent]) > 0 and self.recent_coop[opponent][-1] == 1:
            trust += self.recent_coop_bonus

        # Mutation: Add reputation trend bonus - if reputation is improving, increase trust
        if opponent in self.reputation_trends:
            trend = self.reputation_trends[opponent]
            if trend > self.trend_threshold:
