                if action == 'cooperate':
                    self.coop_counts[agent] = self.coop_counts.get(agent, 0) + 1
                if self.total_counts[agent] > 0:
                    new_rep = self.coop_counts[agent] / self.total_counts[agent]
                    old_rep = self.reputations.get(agent, self.initial_reputation)
                    self.reputations[agent] = self.reputation_momentum * old_rep + (1 - self.reputation_momentum) * new_rep
                    self.reputations[agent] = max(self.reputation_floor, min(self.reputation_cap, self.reputations[agent]))

        # Update personal scores
        if donor_id == self.agent_id:
            if recipient_action == 'cooperate':
                self.personal_scores[recipient_id] = self.personal_scores.get(recipient_id, 0.5) * 0.9 + 0.1 * 1.0
            else:
                self.personal_scores[recipient_id] = self.personal_scores.get(recipient_id, 0.5) * 0.9 + 0.1 * 0.0
                self.punishment_memory[recipient_id] = self.punishment_memory.get(recipient_id, 0) + 1
        elif recipient_id == self.agent_id:
            if donor_action == 'cooperate':
                self.personal_scores[donor_id] = self.personal_scores.get(donor_id, 0.5) * 0.9 + 0.1 * 1.0
            else:
                self.personal_scores[donor_id] = self.personal_scores.get(donor_id, 0.5) * 0.9 + 0.1 * 0.0
                self.punishment_memory[donor_id] = self.punishment_memory.get(donor_id, 0) + 1

        # Track recent cooperation
        for agent, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if agent not in self.recent_coop:
                self.recent_coop[agent] = []
            if len(self.recent_coop[agent]) >= self.history_length:
                self.recent_coop[agent].pop(0)
            self.recent_coop[agent].append(1 if action == 'cooperate' else 0)

        # Mutation: Update long-term cooperation ratio (exponential moving average)
        for agent, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if action in ('cooperate', 'defect'):
                coop_value = 1 if action == 'cooperate' else 0
                if agent not in self.long_term_coop:
                    self.long_term_coop[agent] = coop_value
                else:
                    self.long_term_coop[agent] = 0.95 * self.long_term_coop[agent] + 0.05 * coop_value

        # New mutation: Update recent defections window for each agent
        for agent, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if action == 'defect':
                if agent not in self.recent_defections:
                    self.recent_defections[agent] = 0
                self.recent_defections[agent] += 1
                # Keep only the last defection_window observations
                if self.recent_defections[agent] > self.defection_window:
                    self.recent_defections[agent] = self.defection_window
            else:
                # If cooperating, optionally clear recent defections (forgiveness)
                if agent in self.recent_defections and self.recent_defections[agent] > 0:
                    self.recent_defections[agent] = max(0, self.recent_defections[agent] - 1)

        # Decay punishment memory over time
        if donor_id == self.agent_id and recipient_action == 'cooperate':
            if recipient_id in self.punishment_memory and self.punishment_memory[recipient_id] > 0:
                self.punishment_memory[recipient_id] -= 1
        if recipient_id == self.agent_id and donor_action == 'cooperate':
            if donor_id in self.punishment_memory and self.punishment_memory[donor_id] > 0:
                self.punishment_memory[donor_id] -= 1

        # Track own last action and opponent
        if donor_id == self.agent_id:
            self.last_own_action = donor_action
            self.last_opponent = recipient_id
        elif recipient_id == self.agent_id:
            self.last_own_action = recipient_action
            self.last_opponent = donor_id

        # Update last interaction time
        for agent in [donor_id, recipient_id]:
            self.last_interaction[agent] = self.observation_count

        # Set base trust for unknown agents
        if opponent := getattr(self, '_ctx_opponent_id', None):
            if opponent not in self.reputations:
                self.reputations[opponent] = self.unknown_coop_threshold

        # New mutation: Track reciprocal behavior with partners
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            partner = recipient_id if donor_id == self.agent_id else donor_id
            my_action = donor_action if donor_id == self.agent_id else recipient_action
            partner_action = recipient_action if donor_id == self.agent_id else donor_action

import math
