        if random.random() < 0.05:
            return random.random() < 0.6

        if trust < dynamic_threshold - 0.1:
            return False
        if trust > dynamic_threshold + 0.1:
            return True
        return random.random() < self.generosity

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.observation_count += 1

        # Count third-party defections observed
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            if donor_action == 'defect':
                self.observed_defections += 1
                self.observed_defection_counts[donor_id] = self.observed_defection_counts.get(donor_id, 0) + 1
            if recipient_action == 'defect':
                self.observed_defections += 1
                self.observed_defection_counts[recipient_id] = self.observed_defection_counts.get(recipient_id, 0) + 1
            # Track third-party cooperation counts
            for agent, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
                self.third_party_total_counts[agent] = self.third_party_total_counts.get(agent, 0) + 1
                if action == 'cooperate':
                    self.third_party_coop_counts[agent] = self.third_party_coop_counts.get(agent, 0) + 1
            # Additional mutation: Track if an agent defects against another defector (punishment)
            for agent, action, other_action in [(donor_id, donor_action, recipient_action), (recipient_id, recipient_action, donor_action)]:
                if action == 'defect' and other_action == 'defect':
                    self.third_party_punishment_actions[agent] = self.third_party_punishment_actions.get(agent, 0) + 1

        # Update own reputation based on observations of others' actions toward me
        if donor_id == self.agent_id:
            # When I am the donor, my action affects my reputation as seen by others
            if donor_action == 'cooperate':
                self.self_reputation = min(0.95, self.self_reputation + 0.01)
            else:
                self.self_reputation = max(0.05, self.self_reputation - 0.01)
        elif recipient_id == self.agent_id:
            # When I am the recipient, the donor's action affects my reputation (being cooperated with is good)
            if donor_action == 'cooperate':
                self.self_reputation = min(0.95, self.self_reputation + 0.005)
            else:
                self.self_reputation = max(0.05, self.self_reputation - 0.005)

        for agent, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if action in ('cooperate', 'defect'):
                self.total_counts[agent] = self.total_counts.get(agent, 0) + 1
                if action == 'cooperate':
                    self.coop_counts[agent] = self.coop_counts.get(agent, 0) + 1
                    # Mutation: Track long-term cooperation
                    self.long_term_coop[agent] = self.long_term_coop.get(agent, 0) + 1
                if self.total_counts[agent] > 0:
                    new_rep = self.coop_counts[agent] / self.total_counts[agent]
                    old_rep = self.reputations.get(agent, self.initial_reputation)
                    self.reputations[agent] = self.reputation_momentum * old_rep + (1 - self.reputation_momentum) * new_rep
                    self.reputations[agent] = max(self.reputation_floor, min(self.reputation_cap, self.reputations[agent]))

        # Update personal scores and track defections against me
        if donor_id == self.agent_id:
            if recipient_action == 'cooperate':
                self.personal_scores[recipient_id] = self.personal_scores.get(recipient_id, 0.5) * 0.9 + 0.1 * 1.0
            else:
                self.personal_scores[recipient_id] = self.personal_scores.get(recipient_id, 0.5) * 0.9 + 0.1 * 0.0
                self.punishment_memory[recipient_id] = self.punishment_memory.get(recipient_id, 0) + 1
                self.defections_against_me += 1
                # Mutation: Track repeat defections against me
                self.defections_against_me_count[recipient_id] = self.defections_against_me_count.get(recipient_id, 0) + 1
        elif recipient_id == self.agent_id:
            if donor_action == 'cooperate':
                self.personal_scores[donor_id] = self

