        self.high_rep_trust_bonus = 0.25
        self.high_rep_threshold = 0.85
        # Mutation: Add a penalty for partners with low reputation
        self.low_rep_penalty = 0.15
        self.low_rep_threshold = 0.2
        # Mutation: Reduced sensitivity to recent defections by high-reputation partners
        self.rep_forgiveness = 0.3
        # Mutation: Track long-term cooperation ratio for better stability
        self.long_term_coop = {}
        self.long_term_threshold = 0.7
        self.long_term_bonus = 0.2

