        self.distrust_decay = 0.05
        # Mutation: Add a reputation threshold for strong cooperation with high-reputation partners
        self.high_rep_coop_threshold = 0.8
        # Mutation: Add a bonus for cooperating with partners who have a high reputation
        self.high_rep_bonus = 0.15
        # Mutation: Add a penalty for past defections against us that is proportional to time
        self.time_weighted_penalty = 0.1

        # Mutation: Add a forgiveness factor to reduce punishment memory faster for cooperative partners
        self.forgiveness_factor = 0.3
        # Mutation: Add a recent cooperation bonus to increase trust for recent cooperative behavior
        self.recent_coop_bonus = 0.1
        # Mutation: Add a reputation trend tracking to reward improving reputations
        self.reputation_trends = {}
        self.trend_threshold = 0.02

        # Mutation: Add a long-term memory of interactions to detect stable cooperative patterns
        self.long_term_coop = {}
        # Mutation: Add a suspicion factor that increases when an opponent defects after a long cooperative streak
        self.suspicion_factor = 0.15
        # Mutation: Add a threshold for the number of consecutive cooperations before suspicion kicks in
        self.suspicion_threshold = 5

        # NEW MUTATION: Add a reputation stability factor - trust partners with stable reputations more
        self.reputation_stability = {}
        self.stability_bonus = 0.1
        self.stability_threshold = 0.05

        # NEW MUTATION: Add a reciprocity tracking to be more forgiving if the opponent reciprocates our cooperation
        self.reciprocity_tracker = {}
        self.reciprocity_tolerance = 0.1
        self.reciprocity_memory = 5

        # NEW MUTATION: Add a long-term cooperation count to reward consistent partners
        self.long_term_coop_count = {}
        # NEW MUTATION: Add a threshold for long-term cooperation to give a bonus
        self.long_term_coop_threshold = 5
        # NEW MUTATION: Add a bonus for long-term cooperative partners
        self.long_term_coop_bonus = 0.2

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True

        rep = self.get_reputation(opponent)
        personal = self.personal_scores.get(opponent, 0.5)
        trust = self.personal_weight * personal + (1 - self.personal_weight) * rep

        # Punish known defectors more harshly
        if opponent in self.punishment_memory:
            punish_count = self.punishment_memory[opponent]
            if punish_count >= 3:
                if random.random() < self.risk_threshold:
                    return True
                return False
            trust -= self.punishment_scale * punish_count

        # New mutation: Strong bonus for cooperating with high-reputation partners
        if rep > self.high_rep_coop_threshold:
            trust += self.high_rep_bonus

        # New mutation: Time-weighted penalty for past defections against us
        if opponent in self.punishment_memory:
            time_since_last = self.observation_count - self.last_interaction.get(opponent, 0)
            if time_since_last > 0:
                trust -= self.time_weighted_penalty * punish_count * (1 / (1 + time_since_last * 0.1))

        # New mutation: Cooperation commitment - if we've cooperated with this opponent often recently, increase trust
        if opponent in self.cooperation_commitment and self.cooperation_commitment[opponent] > 0:
            trust += self.cooperation_commitment[opponent] * 0.1

        # New mutation: Distrust decay - if opponent cooperates, reduce negative personal score
        if opponent in self.personal_scores and self.personal_scores[opponent] < 0.5:
            if opponent in self.recent_coop and len(self.recent_coop[opponent]) > 0 and self.recent_coop[opponent][-1] == 1:
                self.personal_scores[opponent] = min(0.5, self.personal_scores[opponent] + self.distrust_decay)

        # Original logic from parent
        if opponent == self.last_opponent and self.last_own_action == 'cooperate':
            if opponent in self.recent_coop and len(self.recent_coop[opponent]) > 0:
                last_opponent_action = self.recent_coop[opponent][-1]
                if last_opponent_action == 1:
                    trust += self.reciprocity_bonus

        if opponent in self.punishment_memory and rep > 0.7:
            punish_count = self.punishment_memory[opponent]
            trust += self.forgiveness * punish_count

        if opponent in self.recent_coop and len(self.recent_coop[opponent]) >= 2:
            recent = self.recent_coop[opponent][-5:]
            if len(recent) > 1:
                changes = sum(1 for i in range(1, len(recent)) if recent[i] != recent[i-1])
                volatility_factor = changes / max(1, len(recent) - 1)
                trust -= self.volatility * volatility_factor

        if opponent in self.recent_coop and len(self.recent_coop[opponent]) >= 5:
            recent = self.recent_coop[opponent][-5:]
            if all(action == 1 for action in recent):
                trust += self.consistency_bonus

        if opponent in self.recent_coop and len(self.recent_coop[opponent]) >= 6:
            recent = self.recent_coop[opponent][-6:]
            first_half = sum(recent[:3])
            second_half = sum(recent[3:])
            if second_half > first_half:
                trust += self.trend_bonus

        if opponent in self.last_interaction:
            rounds_since = self.observation_count - self.last_interaction[opponent]
            trust -= self.trust_decay * rounds_since

        if opponent in self.punishment_memory and self.punishment_memory[opponent] >= self.retaliation_threshold:
            trust -= 0.2

        # Mutation: Add recent cooperation bonus - if the opponent cooperated in the last interaction, increase trust
        if opponent in self.recent_coop and len(self.recent_coop[opponent]) > 0 and self.recent_coop[opponent][-1] == 1:
            trust += self.recent_coop_bonus

        # Mutation: Add reputation trend bonus - if reputation is improving, increase trust
        if opponent in self.reputation_trends:
            trend = self.reputation_trends[opponent]
            if trend > self.trend_threshold:
                trust += min(0.1, trend * 2)

        # New mutation: Suspicion of long cooperative streaks - if opponent has cooperated many times consecutively, be cautious of a sudden defection
        if opponent in self.recent_coop and len(self.recent_coop[opponent]) >= self.suspicion_threshold:
            recent = self.recent_coop[opponent][-self.suspicion_threshold:]
            if all(action == 1 for action in recent):
                trust -= self.suspicion_factor

        # NEW MUTATION: Reputation stability bonus - if opponent's reputation has been stable (low variance), increase trust
        if opponent in self.reputation_stability:
            stability = self.reputation_stability[opponent]
            if stability < self.stability_threshold:
                trust += self.stability_bonus

        # NEW MUTATION: Reciprocity bonus - if we have cooperated with this opponent and they have reciprocated, increase trust
        if opponent in self.reciprocity_tracker:
            history = self.reciprocity_tracker[opponent]
            if len(history) >= 2:
                # Check if opponent tends to reciprocate our cooperation
                coop_count = sum(1 for i in range(1, len(history)) if history[i] == 1 and history[i-1] == 1)
                total_opportunities = sum(1 for i in range(1, len(history)) if history[i-1] == 1)
                if total_opportunities > 0 and coop_count / total_opportunities > 0.7:
                    trust += self.reciprocity_tolerance

        # NEW MUTATION: Long-term cooperation bonus - if we've cooperated with this opponent many times, increase trust
        if opponent in self.long_term_coop_count and self.long_term_coop_count[opponent] >= self.long_term_coop_threshold:
            trust += self.long_term_coop_bonus

        dynamic_threshold = self.trust_threshold - (self.observation_count * 0.001)
        dynamic_threshold = max(0.2, min(0.8, dynamic_threshold))

        self.generosity = max(0.3, self.generosity - self.generosity_decay)
        self.cautiousness = min(0.3, self.cautiousness + self.cautiousness_increment)
        trust -= self.cautiousness

        if random.random() < 0.05:
            return random.random() < 0.6

        if trust < dynamic_threshold - 0.1:
            return random.random() < self.base_coop_probability
        if trust > dynamic_threshold + 0.1:
            return True
        return random.random() < self.generosity

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.observation_count += 1

        for agent, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
