                self.punishment_memory[recipient_id] = self.punishment_memory.get(recipient_id, 0) + 1
                self.defections_against_me += 1
                # Mutation: Track repeat defections against me
                self.defections_against_me_count[recipient_id] = self.defections_against_me_count.get(recipient_id, 0) + 1
        elif recipient_id == self.agent_id:
            if donor_action == 'cooperate':
