        self.recent_defections = {}
        self.defection_window = 5
        self.defection_penalty = 0.1

        # NEW MUTATION: Track the frequency of cooperation by each agent, and add a bonus for agents who cooperate frequently (i.e., are "cooperative" by nature)
        self.cooperation_frequency = {}
        self.frequency_weight = 0.2
        self.frequency_threshold = 0.8

        # NEW MUTATION: Track how many times an agent has been observed cooperating with others (a form of third-party reputation)
        self.third_party_coop_counts = {}
        self.third_party_total_counts = {}
        self.third_party_bonus = 0.1

        # NEW MUTATION: Track consistency of cooperation over time for each agent
        self.cooperation_consistency = {}
        self.consistency_weight = 0.1
        self.consistency_threshold = 0.7

        # NEW MUTATION: Track whether agents are more cooperative with those who cooperate with them (conditional cooperation)
        self.conditional_cooperation = {}
        self.conditional_weight = 0.1
        self.conditional_threshold = 0.6

        # NEW MUTATION: Track the ratio of cooperation when facing high-reputation opponents
        self.reputation_sensitivity = {}
        self.rep_sensitivity_weight = 0.15
        self.rep_sensitivity_threshold = 0.7

        # NEW MUTATION: Track opponent's tendency to cooperate with high-reputation agents
        self.reputation_dependent_coop = {}
        self.rep_dep_weight = 0.1
        self.rep_dep_threshold = 0.7

        # NEW MUTATION: Track recent cooperation trend (whether agent is improving or worsening)
        self.coop_trend = {}
        self.trend_window = 5
        self.trend_weight = 0.1

        # NEW MUTATION: Track how often an agent cooperates after being defected against (forgiveness tendency)
        self.forgiveness_tendency = {}
        self.forgiveness_weight = 0.1
        self.forgiveness_threshold = 0.5

        # NEW MUTATION: Track the consistency of an agent's cooperation with respect to reputation of opponent
        self.reputation_consistency = {}
        self.rep_consistency_weight = 0.05

        # NEW MUTATION: Track the urgency of cooperation based on time since last interaction
        self.time_urgency = {}
        self.urgency_weight = 0.08
        self.urgency_threshold = 5

        # NEW MUTATION: Track the opponent's tendency to cooperate when they are in a losing streak
        self.streak_sensitivity = {}
        self.streak_weight = 0.08
        self.streak_threshold = 2

        # NEW MUTATION: Track the opponent's tendency to cooperate when they have high reputation and we have low reputation
        self.asymmetry_sensitivity = {}
        self.asymmetry_weight = 0.06

        # NEW MUTATION: Add a dynamic exploration factor that increases when in losing streaks
        self.exploration_factor = 0.05
        self.exploration_increment = 0.01
        self.exploration_max = 0.2

        # NEW MUTATION: Add a dynamic threshold that becomes stricter after multiple defections
        self.defection_penalty_multiplier = 1.0
        self.defection_penalty_increment = 0.05
        self.defection_penalty_max = 2.0

        # NEW MUTATION: Track a longer history for better pattern detection
        self.long_history = {}
        self.long_history_length = 20

        # NEW MUTATION: Add a bonus for agents who cooperate in the first interaction (initial trust)
        self.initial_coop_bonus = 0.1
