import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputations = {}
        self.coop_counts = {}
        self.total_counts = {}
        self.personal_scores = {}
        self.recent_coop = {}
        self.generosity = 0.7
        self.trust_threshold = 0.5
        self.initial_reputation = 0.6
        self.punishment_memory = {}
        self.last_own_action = None
        self.last_opponent = None
        self.reciprocity_bonus = 0.1
        self.forgiveness = 0.2
        self.reputation_momentum = 0.8
        self.risk_threshold = 0.3
        self.volatility = 0.1
        self.generosity_decay = 0.01
        self.personal_weight = 0.4
        self.observation_count = 0
        self.consistency_bonus = 0.05
        self.cautiousness = 0.0
        self.cautiousness_increment = 0.005
        self.reputation_cap = 0.95
        self.reputation_floor = 0.05
        self.history_length = 10
        self.trend_bonus = 0.08
        self.trust_decay = 0.02
        self.last_interaction = {}
        self.retaliation_threshold = 2
        self.social_learning_rate = 0.15
        self.exploitation_bias = 0.0
        self.exploitation_increment = 0.02
        self.defections_against_me = 0
        self.third_party_defection_penalty = 0.05
        self.observed_defections = 0
        self.third_party_coop_counts = {}
        self.third_party_total_counts = {}
        self.social_coop_bonus = 0.1
        self.direct_interaction_history = {}
        self.strong_reciprocity_bonus = 0.15
        # Mutation: Add a reputation bias that favors agents with high social standing
        self.social_status_bias = 0.05
        # Mutation: Track the number of times this agent has cooperated with others
        self.cooperations_by_me = 0
        self.defections_by_me = 0
        # Mutation: Introduce a memory of own recent actions to adjust generosity
        self.own_recent_actions = []
        # Mutation: Add a bias to cooperate more with agents that have been consistently cooperative in the long run
        self.long_term_coop_bias = 0.1
        # Mutation: Track long-term cooperation for each agent
        self.long_term_coop = {}
        # Mutation: Add a norm-based multiplier that amplifies the social status bias and long-term bias
        self.norm_multiplier = 1.0
        # Mutation: Add a penalty for agents who defect against me multiple times
        self.repeat_defection_penalty = 0.15
        # Mutation: Track the number of times each agent has defected against me
        self.defections_against_me_count = {}
        # New mutation: Add a tendency to punish defectors more strongly when observed in third-party interactions
        self.third_party_punishment_bonus = 0.1
        # New mutation: Track observed defection frequency for each agent
        self.observed_defection_counts = {}
        # New mutation: Add a reputation penalty for agents with high observed defection rates
        self.observed_defection_penalty = 0.08
        # Additional mutation: Track the reputation of the agent itself based on others' observations
        self.self_reputation = self.initial_reputation
        # Additional mutation: Track recent third-party punishment actions (defections against defectors) to influence trust
        self.third_party_punishment_actions = {}

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        if opponent is None:
            return True

        rep = self.get_reputation(opponent)
        personal = self.personal_scores.get(opponent, 0.5)
        trust = self.personal_weight * personal + (1 - self.personal_weight) * rep

        # Punish known defectors more harshly
        if opponent in self.punishment_memory:
            punish_count = self.punishment_memory[opponent]
            if punish_count >= 3:
                if random.random() < self.risk_threshold:
                    return True
                return False
            trust -= 0.1 * punish_count

        # Social learning from third-party observations
        if opponent in self.reputations and self.reputations[opponent] > 0.8:
            trust += self.social_learning_rate

        # If opponent has been observed defecting against others, reduce trust
        if opponent in self.recent_coop:
            coop_rate = sum(self.recent_coop[opponent]) / max(1, len(self.recent_coop[opponent]))
            if coop_rate < 0.3:
                trust -= self.social_learning_rate * 0.5

        # Increase cautiousness when defected against recently
        if self.defections_against_me > 0:
            trust -= self.exploitation_bias * self.defections_against_me

        # Reciprocity bonus if opponent cooperated last time we interacted
        if opponent == self.last_opponent and self.last_own_action == 'cooperate':
            if opponent in self.recent_coop and len(self.recent_coop[opponent]) > 0:
                last_opponent_action = self.recent_coop[opponent][-1]
                if last_opponent_action == 1:
                    trust += self.reciprocity_bonus
                    if opponent in self.direct_interaction_history and self.direct_interaction_history[opponent].get('last_action') == 1:
                        trust += self.strong_reciprocity_bonus

        # Forgiveness component
        if opponent in self.punishment_memory and rep > 0.7:
            punish_count = self.punishment_memory[opponent]
            trust += self.forgiveness * punish_count

        # Volatility adjustment
        if opponent in self.recent_coop and len(self.recent_coop[opponent]) >= 2:
            recent = self.recent_coop[opponent][-5:]
            if len(recent) > 1:
                changes = sum(1 for i in range(1, len(recent)) if recent[i] != recent[i-1])
                volatility_factor = changes / max(1, len(recent) - 1)
                trust -= self.volatility * volatility_factor

        # Consistency bonus
        if opponent in self.recent_coop and len(self.recent_coop[opponent]) >= 5:
            recent = self.recent_coop[opponent][-5:]
            if all(action == 1 for action in recent):
                trust += self.consistency_bonus

        # Trend bonus
        if opponent in self.recent_coop and len(self.recent_coop[opponent]) >= 6:
            recent = self.recent_coop[opponent][-6:]
            first_half = sum(recent[:3])
            second_half = sum(recent[3:])
            if second_half > first_half:
                trust += self.trend_bonus

        # Trust decay
        if opponent in self.last_interaction:
            rounds_since = self.observation_count - self.last_interaction[opponent]
            trust -= self.trust_decay * rounds_since

        # Retaliation
        if opponent in self.punishment_memory and self.punishment_memory[opponent] >= self.retaliation_threshold:
            trust -= 0.2

        # Penalize trust for opponents observed defecting in third-party interactions
        if opponent in self.recent_coop:
            coop_rate = sum(self.recent_coop[opponent]) / max(1, len(self.recent_coop[opponent]))
            if coop_rate < 0.5:
                trust -= self.third_party_defection_penalty * (1 - coop_rate) * 2

        # Boost trust for agents that cooperate in third-party interactions
        if opponent in self.third_party_total_counts and self.third_party_total_counts[opponent] > 0:
            third_party_coop_rate = self.third_party_coop_counts.get(opponent, 0) / self.third_party_total_counts[opponent]
            if third_party_coop_rate > 0.7:
                trust += self.social_coop_bonus

        # Mutation: Add social status bias based on the opponent's reputation relative to the average
        if self.reputations:
            avg_rep = sum(self.reputations.values()) / len(self.reputations)
            if rep > avg_rep:
                trust += self.social_status_bias * self.norm_multiplier
            else:
                trust -= self.social_status_bias * self.norm_multiplier

        # Mutation: Add long-term cooperation bias
        if opponent in self.long_term_coop and self.long_term_coop[opponent] > 0:
            long_term_rate = self.long_term_coop[opponent] / max(1, self.total_counts.get(opponent, 0))
            if long_term_rate > 0.7:
                trust += self.long_term_coop_bias * self.norm_multiplier
            elif long_term_rate < 0.3:
                trust -= self.long_term_coop_bias * 0.5 * self.norm_multiplier

        # Mutation: Add penalty for repeat defections against me
        if opponent in self.defections_against_me_count:
            repeat_defections = self.defections_against_me_count[opponent]
            if repeat_defections >= 2:
                trust -= self.repeat_defection_penalty * (repeat_defections - 1)

        # New mutation: Add penalty for high observed defection rate in third-party interactions
        if opponent in self.observed_defection_counts:
            observed_defections = self.observed_defection_counts[opponent]
            observed_total = self.third_party_total_counts.get(opponent, 0)
            if observed_total > 0:
                observed_defection_rate = observed_defections / observed_total
                if observed_defection_rate > 0.6:
                    trust -= self.observed_defection_penalty * (observed_defection_rate - 0.6) * 5

        # Additional mutation: Adjust trust based on whether the opponent has been observed punishing defectors
        if opponent in self.third_party_punishment_actions:
            punish_count = self.third_party_punishment_actions[opponent]
            trust += min(0.2, 0.05 * punish_count) * self.social_learning_rate

        # Dynamic threshold
        dynamic_threshold = self.trust_threshold - (self.observation_count * 0.001)
        dynamic_threshold = max(0.2, min(0.8, dynamic_threshold))

        # Generosity decay
        self.generosity = max(0.3, self.generosity - self.generosity_decay)

        # Cautiousness increase
        self.cautiousness = min(0.3, self.cautiousness + self.cautiousness_increment)
        trust -= self.cautiousness

        # Exploitation bias increase if we've been defected against a lot
        if self.defections_against_me > 3:
            self.exploitation_bias = min(0.3, self.exploitation_bias + self.exploitation_increment)

        # Mutation: Adjust generosity based on own recent cooperation rate
        if len(self.own_recent_actions) >= 5:
            coop_rate_own = sum(self.own_recent_actions[-5:]) / 5
            if coop_rate_own > 0.8:
                self.generosity = min(0.9, self.generosity + 0.05)
            elif coop_rate_own < 0.2:
                self.generosity = max(0.3, self.generosity - 0.05)

        # Random exploration
        if random.random() < 0.05:
            return random.random() < 0.6

        if trust < dynamic_threshold - 0.1:
            return False
        if trust > dynamic_threshold + 0.1:
            return True
        return random.random() < self.generosity

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        self.observation_count += 1

        # Count third-party defections observed
        if donor_id != self.agent_id and recipient_id != self.agent_id:
            if donor_action == 'defect':
                self.observed_defections += 1
                self.observed_defection_counts[donor_id] = self.observed_defection_counts.get(donor_id, 0) + 1
            if recipient_action == 'defect':
                self.observed_defections += 1
