        if opponent is None:
            return True

        rep = self.get_reputation(opponent)
        personal = self.personal_scores.get(opponent, 0.5)
        trust = self.personal_weight * personal + (1 - self.personal_weight) * rep

        # Punish known defectors more harshly
        if opponent in self.punishment_memory:
            punish_count = self.punishment_memory[opponent]
            if punish_count >= 3:
                if random.random() < self.risk_threshold:
                    return True
                return False
            trust -= 0.1 * punish_count

        # Social learning from third-party observations
        if opponent in self.reputations and self.reputations[opponent] > 0.8:
            trust += self.social_learning_rate

        # If opponent has been observed defecting against others, reduce trust
        if opponent in self.recent_coop:
            coop_rate = sum(self.recent_coop[opponent]) / max(1, len(self.recent_coop[opponent]))
            if coop_rate < 0.3:
