            for agent, action, other_action in [(donor_id, donor_action, recipient_action), (recipient_id, recipient_action, donor_action)]:
                if action == 'defect' and other_action == 'defect':
                    self.third_party_punishment_actions[agent] = self.third_party_punishment_actions.get(agent, 0) + 1

        # Update own reputation based on observations of others' actions toward me
        if donor_id == self.agent_id:
            # When I am the donor, my action affects my reputation as seen by others
            if donor_action == 'cooperate':
                self.self_reputation = min(0.95, self.self_reputation + 0.01)
            else:
                self.self_reputation = max(0.05, self.self_reputation - 0.01)
        elif recipient_id == self.agent_id:
            # When I am the recipient, the donor's action affects my reputation (being cooperated with is good)
            if donor_action == 'cooperate':
                self.self_reputation = min(0.95, self.self_reputation + 0.005)
            else:
                self.self_reputation = max(0.05, self.self_reputation - 0.005)

        for agent, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if action in ('cooperate', 'defect'):
                self.total_counts[agent] = self.total_counts.get(agent, 0) + 1
                if action == 'cooperate':
                    self.coop_counts[agent] = self.coop_counts.get(agent, 0) + 1
                if self.total_counts[agent] > 0:
                    new_rep = self.coop_counts[agent] / self.total_counts[agent]
