                self.observed_defection_counts[donor_id] = self.observed_defection_counts.get(donor_id, 0) + 1
            if recipient_action == 'defect':
                self.observed_defections += 1
                self.observed_defection_counts[recipient_id] = self.observed_defection_counts.get(recipient_id, 0) + 1
            # Track third-party cooperation counts
            for agent, action in [(donor_id, donor_action), (recipient_id, recipient_action)]:
